insert into _bookkeeping_knowledge_fix values
(1, 1, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Which statement best describes the main purpose of bookkeeping?”, the proposed answer is “To predict future profits without using transaction evidence”.","answer":false,"feedback":"Bookkeeping creates and maintains reliable transaction records from appropriate evidence. It is broader than bank entries, but it does not replace every accounting or tax responsibility."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A customer pays R5,000 that was already recorded as owing on their account. What is the most appropriate bookkeeping action?”, the proposed answer is “Ignore the receipt because the sale was already recorded”.","answer":false,"feedback":"The payment should be allocated against the existing debtor/customer balance. Recording another sale would duplicate income."},{"id":"q3","answer":2,"prompt":"Which item is the best example of source evidence for a supplier purchase?","options":["An unsupported verbal instruction","A personal note written later from memory","A supplier invoice","A sales forecast"],"feedback":"A supplier invoice is documentary evidence supporting the purchase. Bookkeeping should start from reliable evidence rather than memory or unsupported assumptions.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should a bookkeeper do when unsure about specialised tax treatment?”, the proposed answer is “Choose the treatment that produces the lowest tax”.","answer":false,"feedback":"Uncertain technical treatment should be escalated. The bookkeeper should not invent tax treatment outside their competence or authority."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Transaction","right":"A financial event that affects the business, such as a sale, purchase, payment or receipt."},{"left":"Source document","right":"Evidence supporting a transaction, such as an invoice, receipt or bank statement."},{"left":"Bookkeeping","right":"Recording and maintaining financial transactions and related records."},{"left":"Accounting","right":"Broader process of analysing, interpreting, reporting and using financial information."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(1, 2, '{"version":2,"questions":[{"id":"q1","answer":2,"prompt":"Which equation correctly describes the basic relationship between assets, liabilities and equity?","options":["Income = Assets - Liabilities","Assets = Income + Expenses","Assets = Liabilities + Equity","Assets + Liabilities = Equity"],"feedback":"The basic accounting equation is Assets = Liabilities + Equity. It can also be rearranged as Equity = Assets - Liabilities.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A business receives a R10,000 bank loan. Which effect is correct?”, the proposed answer is “Bank increases and a loan liability increases”.","answer":true,"feedback":"Borrowed money increases the Bank asset and creates or increases a liability. The loan is not revenue earned from a customer."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Office equipment is purchased and the Equipment asset increases. On which side is the increase recorded?”, the proposed answer is “Either side always has the same effect”.","answer":false,"feedback":"Assets normally increase with debits and decrease with credits."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A customer pays an amount that was already recorded as owing. What is the correct basic entry?”, the proposed answer is “Debit Bank; Credit Accounts Receivable/Debtors”.","answer":true,"feedback":"Bank increases, so it is debited. The receivable decreases, so it is credited. Recording sales revenue again would duplicate the sale."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Asset","right":"Resource controlled by the business from which future economic benefit is expected."},{"left":"Liability","right":"Present obligation of the business to another party."},{"left":"Owners'' equity","right":"The owner''s residual interest in the business after liabilities are deducted from assets."},{"left":"Debit","right":"Left side of an account."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(1, 3, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Which statement about a South African sole proprietorship is correct?”, the proposed answer is “It is owned by a natural person and is not a legal entity separate from that owner”.","answer":true,"feedback":"A sole proprietorship is owned and operated by a natural person and does not have legal existence separate from that owner. Bookkeeping should nevertheless separate business and private activity."},{"id":"q2","answer":3,"prompt":"A sole proprietor uses R900 from the business bank account to buy private groceries. What is the most appropriate basic bookkeeping classification?","options":["Office expense incurred for the ordinary operations of the business","Sales expense","Business income","Drawings / personal withdrawal"],"feedback":"Personal value taken by the proprietor is normally recorded as drawings rather than as an operating expense.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A shareholder transfers R40,000 to a company and provides no explanation. What should the bookkeeper do first?”, the proposed answer is “Obtain supporting documentation or clarification before deciding whether it is equity, a loan, repayment or another item”.","answer":true,"feedback":"A shareholder''s payment to a company can have several possible meanings. The classification must follow the evidence and economic substance, not the person''s status as shareholder."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should a company''s payment of a director''s private expense not automatically be recorded as a normal business expense?”, the proposed answer is “Because the company is a separate legal person and the transaction may require recovery or another authorised accounting, remuneration, distribution or tax treatment”.","answer":true,"feedback":"A company is separate from its shareholders and directors. A private benefit paid by the company needs proper classification and may require specialist judgement."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Sole proprietor","right":"Individual who operates a business in their own capacity."},{"left":"Partnership","right":"Business arrangement in which two or more partners conduct business together under agreed terms."},{"left":"Company","right":"Separate legal entity incorporated under company law."},{"left":"Capital contribution","right":"Value introduced into the business by an owner or shareholder according to the relevant structure."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(1, 4, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should normally happen before a transaction is captured into the accounting system?”, the proposed answer is “The transaction should be posted to a random account and corrected later”.","answer":false,"feedback":"Reliable bookkeeping begins with evidence, checking and transaction analysis before capture or posting."},{"id":"q2","answer":1,"prompt":"What is the main purpose of a reconciliation?","options":["To force two balances to agree even if the reason is unknown","To compare related records and investigate differences","To prove that every ledger entry is correct","To replace source documents"],"feedback":"Reconciliation compares records that should relate to one another and requires unexplained differences to be investigated, not hidden.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A trial balance has equal total debits and credits. What can you safely conclude?”, the proposed answer is “Every transaction is complete and correctly classified”.","answer":false,"feedback":"A balanced trial balance confirms debit-credit equality, but omissions, duplicates, misclassifications and other errors can still remain."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Which situation is most likely to require an authorised period-end adjustment rather than routine daily capture?”, the proposed answer is “Recognising period-end depreciation according to the entity''s approved accounting treatment”.","answer":true,"feedback":"Depreciation is a common period-end adjustment. The exact treatment and authority depend on the entity''s accounting framework and procedures."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Bookkeeping cycle","right":"Sequence of activities used to record, classify, check and report financial transactions."},{"left":"Journal","right":"Book or system record in which transactions are initially grouped or recorded."},{"left":"Ledger","right":"Collection of accounts showing transaction movements and balances."},{"left":"Trial balance","right":"List of ledger balances used to check debit and credit equality."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(1, 5, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"Which action best demonstrates integrity after discovering that an invoice was captured twice?","options":["Move one entry to another supplier","Delete evidence of the duplicate so no one notices","Leave both entries unchanged because equal debits and credits mean the duplicate cannot affect the financial records","Correct the duplicate through the approved process and preserve the traceable correction"],"feedback":"An honest error should be corrected transparently through the approved process, with enough evidence for the correction to be understood later.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A senior manager asks you to record an unsupported personal cost as a business expense. What is the safest response?”, the proposed answer is “Do not misrepresent the transaction; obtain evidence or clarification and escalate unresolved treatment through the authorised channel”.","answer":true,"feedback":"Seniority does not justify changing the facts. Unsupported treatment should be clarified or escalated rather than invented."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Your close relative owns a supplier and you are asked to independently approve that supplier''s transaction. What should you do?”, the proposed answer is “Disclose the conflict of interest and follow the organisation''s process for independent review or approval”.","answer":true,"feedback":"A relationship does not prove wrongdoing, but it can affect or appear to affect objectivity. Disclosing the conflict allows the organisation to manage it appropriately."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A colleague asks you to send them another employee''s salary information because they are curious. What is the correct response?”, the proposed answer is “Post it in a team chat so everyone has the same information”.","answer":false,"feedback":"Confidential financial and personal information should only be disclosed to authorised people for a legitimate work purpose."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Integrity","right":"Acting honestly and consistently with professional and organisational standards."},{"left":"Confidentiality","right":"Protecting information from unnecessary or unauthorised disclosure."},{"left":"Objectivity","right":"Avoiding bias, personal interest or pressure that distorts judgement."},{"left":"Conflict of interest","right":"Situation where personal interests could interfere with professional responsibilities."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(1, 6, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Which statement best describes the accrual basis of accounting?”, the proposed answer is “Transactions are recognised only when money enters or leaves the bank”.","answer":false,"feedback":"Accrual accounting recognises the effects of transactions and events in the periods to which they relate. Cash information remains important, but cash timing is not always the same as accounting timing."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A manager says that every error below R500 is automatically immaterial. What is the best response?”, the proposed answer is “Check the entity''s approved guidance because materiality depends on the nature or magnitude of information, or both, in the entity''s circumstances”.","answer":true,"feedback":"Materiality is entity-specific. There is no universal rand threshold that a bookkeeper should invent or apply without authorised guidance."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What does prudence mean in financial reporting?”, the proposed answer is “Overstate liabilities so the business appears conservative”.","answer":false,"feedback":"Prudence supports careful, neutral judgement under uncertainty. It does not justify deliberately understating assets or income or overstating liabilities or expenses."},{"id":"q4","answer":0,"prompt":"Which statement about the 2025 third edition of the IFRS for SMEs Accounting Standard is correct?","options":["It is effective for annual reporting periods beginning on or after 1 January 2027, with earlier application permitted","It replaced the Companies Act and Companies Regulations","It became mandatory immediately for every South African small business, regardless of its reporting framework, public accountability or legal form","It applies to every entity regardless of public accountability"],"feedback":"The third edition was issued in 2025 and is effective from annual periods beginning on or after 1 January 2027, with early application permitted. Eligibility and use still depend on the applicable jurisdictional requirements.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Accrual basis","right":"Recording income and expenses in the period in which they are earned or incurred, rather than only when cash moves."},{"left":"Consistency","right":"Applying accounting methods in a stable way unless there is a justified change."},{"left":"Materiality","right":"Considering whether information could reasonably matter to users of the financial information."},{"left":"Going concern","right":"Assumption that the entity will continue operating for the foreseeable future unless evidence indicates otherwise."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(1, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the main purpose of a chart of accounts?”, the proposed answer is “To organise and classify transactions consistently for recording and reporting”.","answer":true,"feedback":"A chart of accounts provides the structure used to classify transactions consistently and support useful reporting."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A business already has an account called Courier Expense. What should a bookkeeper do before creating a new account called Delivery Fees for the same type of cost?”, the proposed answer is “Search the existing chart, confirm whether the current account is suitable and follow the approval process”.","answer":true,"feedback":"Duplicate accounts weaken consistency. Existing accounts and approval rules should be checked before a new account is created."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Where should individual customer balances normally be maintained when a control-account system is used?”, the proposed answer is “In a subsidiary customer ledger supporting the control account”.","answer":true,"feedback":"Customer detail normally sits in the subsidiary ledger while the general ledger carries the related control account."},{"id":"q4","answer":2,"prompt":"Is one particular account-numbering sequence legally required for every business?","options":["Yes, all businesses must use 1000 for assets and 2000 for liabilities","Yes, but only companies","No; a business may use a suitable consistent structure","No, because account codes should never be used"],"feedback":"Account coding is an internal design choice. The structure should be consistent and appropriate to the business and system.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Chart of accounts","right":"Organised list of accounts available in the bookkeeping system."},{"left":"Account code","right":"Number or alphanumeric reference used to identify an account."},{"left":"General ledger account","right":"Account that accumulates transactions of a particular type."},{"left":"Control account","right":"Summary ledger account linked to detailed subsidiary records, such as debtors or creditors."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(1, 8, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"Which is the best example of a preventive control?","options":["Correcting an overpayment after it is found","Investigating a month-end variance after reporting","Reviewing a completed bank reconciliation","Requiring authorised approval before a payment is released"],"feedback":"Approval before release is preventive because it is intended to stop an unauthorised payment before it occurs.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A small business does not have enough staff for full separation of duties. What is the most appropriate response?”, the proposed answer is “Allow one employee to control everything without review”.","answer":false,"feedback":"Where full segregation is impractical, compensating controls can provide independent oversight of higher-risk activities."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why should supplier bank-detail changes be independently verified?”, the proposed answer is “To reduce the risk that an incorrect or unauthorised request redirects payment”.","answer":true,"feedback":"Independent verification helps confirm that the change is genuine without assuming that every request is fraudulent."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Which statement about a fraud warning sign is correct?”, the proposed answer is “It can justify verification and escalation but is not proof by itself”.","answer":true,"feedback":"A warning sign is a reason to verify and escalate appropriately, not proof of fraud."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Internal control","right":"Process or procedure designed to protect assets, improve record reliability and support authorised operations."},{"left":"Preventive control","right":"Control intended to stop an error or unauthorised action before it occurs."},{"left":"Detective control","right":"Control intended to identify an error or unusual activity after or while it occurs."},{"left":"Corrective control","right":"Action used to fix an identified problem and reduce recurrence."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 1, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Which statement best describes a source document?”, the proposed answer is “It is evidence created, issued or received because a business transaction or financially relevant event occurred”.","answer":true,"feedback":"A source document is evidence of the underlying event. It supports analysis and recording but is not the ledger itself."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A bank statement shows a payment with the reference ‘TRANSFER’. What can the bookkeeper safely conclude from that alone?”, the proposed answer is “Money moved through the bank, but the business purpose may still require supporting evidence”.","answer":true,"feedback":"A bank entry evidences settlement but may not identify the economic substance of the transaction."},{"id":"q3","answer":3,"prompt":"The system warns that a supplier invoice number already exists. What is the best response?","options":["Capture the second invoice to be safe","Delete the first invoice immediately","Override the warning and capture the invoice again because a supplier may reuse the same reference for separate purchases","Investigate the existing record and supporting evidence before deciding whether another entry is valid"],"feedback":"A duplicate warning is a control signal. It should be investigated rather than automatically overridden or treated as proof of wrongdoing.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A receipt is missing for a transaction. What should the bookkeeper do?”, the proposed answer is “Follow the authorised missing-evidence or exception process and obtain appropriate clarification or alternative evidence”.","answer":true,"feedback":"Missing evidence should be handled through an authorised process. Fabricating evidence damages the audit trail."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Source document","right":"Evidence created or received because a business transaction occurred."},{"left":"Internal document","right":"Document created within the business, such as an approved petty-cash voucher."},{"left":"External document","right":"Document received from or issued to an outside party, such as a supplier invoice."},{"left":"Supporting evidence","right":"Additional information proving or explaining a transaction."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 2, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"A customer pays an invoice that was already recorded as a credit sale. What is the normal bookkeeping effect of the receipt?","options":["Increase Bank and reduce Accounts Receivable/Debtors","Reduce Bank and increase Sales","Record the bank receipt as new sales income because cash was received after the original invoice date","Create a supplier liability"],"feedback":"The payment settles an existing receivable. Recording sales again would duplicate income.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the primary purpose of a customer credit note?”, the proposed answer is “To reduce or reverse an authorised amount previously billed to a customer”.","answer":true,"feedback":"A credit note adjusts a previous customer billing when there is a valid authorised reason."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A bank deposit cannot yet be matched to a customer. What is the safest response?”, the proposed answer is “Investigate the payer and reference and keep it unresolved or unallocated according to policy until it can be identified”.","answer":true,"feedback":"Unidentified receipts should remain visible while the evidence is investigated rather than being guessed into a customer account."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A customer pays more than the known outstanding amount. What should the bookkeeper do?”, the proposed answer is “Investigate whether another invoice, customer credit, refund or payment error explains the overpayment”.","answer":true,"feedback":"An overpayment has several possible explanations and should be investigated before final classification."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Sales invoice","right":"Document issued to a customer showing goods or services supplied and the amount due."},{"left":"Credit note","right":"Document reducing or reversing all or part of a previously billed amount."},{"left":"Receipt","right":"Evidence that money was received."},{"left":"Customer statement","right":"Summary of transactions and balance on a customer''s account for a period."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 3, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the purpose of a three-way match?”, the proposed answer is “To compare the purchase order, receipt evidence and supplier invoice”.","answer":true,"feedback":"A three-way match tests whether what was ordered, received and billed agrees before payment or final approval."},{"id":"q2","answer":2,"prompt":"A supplier credit note normally has what effect on the amount owed to that supplier?","options":["It creates a new customer receivable","It proves a payment was made","It reduces or reverses an authorised amount previously billed","It increases the supplier liability by creating an additional amount payable on the account"],"feedback":"A supplier credit note reduces the supplier balance when correctly linked and processed.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “The business raises a debit note claiming a R2,000 reduction, but the supplier has not yet accepted it. What is the safest treatment?”, the proposed answer is “Follow the dispute process and do not assume the claim is final until the treatment is supported”.","answer":true,"feedback":"A buyer-raised claim may not yet be accepted. The accounting record should follow the evidence and approved process."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the main purpose of reconciling a supplier statement?”, the proposed answer is “To compare the supplier''s account view with the business creditor ledger and investigate differences”.","answer":true,"feedback":"Statement reconciliation identifies missing invoices, credits, payments, allocations and timing differences."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Supplier invoice","right":"Document from a supplier requesting payment for goods or services supplied."},{"left":"Creditor / accounts payable","right":"Amount owed by the business to a supplier."},{"left":"Purchase order (PO)","right":"Authorised order issued to a supplier under the organisation''s purchasing process."},{"left":"Delivery note / goods received evidence","right":"Evidence that goods were received."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 4, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What does an EFT confirmation usually prove most directly?”, the proposed answer is “That an electronic payment movement occurred, subject to the bank record”.","answer":true,"feedback":"EFT evidence supports settlement, but the underlying invoice, agreement or approval may still be needed to explain the business purpose."},{"id":"q2","answer":3,"prompt":"Gross card sales are R10,000 and merchant fees are R250. What is the expected net settlement if there are no other adjustments?","options":["R250","R9,250","R10,250","R9,750"],"feedback":"R10,000 - R250 = R9,750.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A petty-cash float is R2,000, cash on hand is R650 and valid vouchers total R1,300. What is the unexplained difference?”, the proposed answer is “R650 shortage”.","answer":false,"feedback":"R650 + R1,300 = R1,950, which is R50 below the approved R2,000 float."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A company-card receipt shows a hardware purchase. Which feature makes the receipt most useful for classification and verification?”, the proposed answer is “It automatically proves that every item is a business expense”.","answer":false,"feedback":"The card statement shows settlement, while the itemised document provides detail needed for classification and control."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"EFT","right":"Electronic funds transfer between bank accounts."},{"left":"Card transaction","right":"Payment or receipt processed through a debit/credit-card or merchant system."},{"left":"Petty cash","right":"Small controlled cash float used for authorised minor expenditure."},{"left":"Imprest","right":"Petty-cash method that restores the float to an approved fixed amount after documented expenditure."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 5, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should be the first focus in transaction analysis?”, the proposed answer is “Which expense account has the lowest balance”.","answer":false,"feedback":"Economic substance and evidence come before account selection."},{"id":"q2","answer":2,"prompt":"A supplier invoice was recorded last week and is paid today. What does today''s payment normally do?","options":["Increases Sales","Creates the expense again","Reduces Accounts Payable and Bank","Increases the supplier liability"],"feedback":"The expense or asset was recognised when the invoice was recorded. Settlement reduces the existing liability.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A customer pays R4,000 that was already outstanding. Is the receipt automatically new income?”, the proposed answer is “No; it normally increases Bank and reduces the existing receivable”.","answer":true,"feedback":"Collections of existing receivables settle customer balances rather than creating a second sale."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A loan payment of R8,000 contains R6,500 principal, R1,300 interest and R200 fee. What is the safest analysis?”, the proposed answer is “Record the full R8,000 as Interest Expense”.","answer":false,"feedback":"Compound transactions should be split according to their supported components."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Transaction analysis","right":"Determining the financial effect of a business event before or during recording."},{"left":"Account classification","right":"Assigning a transaction to the appropriate account or category."},{"left":"Debit","right":"Left side of an account."},{"left":"Credit","right":"Right side of an account."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 6, '{"version":2,"questions":[{"id":"q1","answer":2,"prompt":"What is South Africa''s standard VAT rate used in this lesson as at October 2026?","options":["12%","16%","15%","14%"],"feedback":"SARS states that the standard VAT rate remains 15% as at October 2026.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “How do you extract VAT from an amount that already includes VAT at 15%?”, the proposed answer is “Inclusive amount × 15/115”.","answer":true,"feedback":"At a 15% rate, the tax fraction 15/115 extracts the VAT component from an inclusive amount."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A standard-rated sale is R5,000 excluding VAT. What is the VAT amount at 15%?”, the proposed answer is “R5,750”.","answer":false,"feedback":"R5,000 × 15% = R750."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Which statement is correct about input tax?”, the proposed answer is “Every VAT amount on every purchase is automatically deductible”.","answer":false,"feedback":"Deductibility depends on legal conditions and supporting documentation; it should not be assumed."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"VAT","right":"Value-Added Tax."},{"left":"VAT vendor","right":"Person/entity registered for VAT under the applicable rules."},{"left":"Standard-rated supply","right":"Taxable supply on which the standard VAT rate applies."},{"left":"Zero-rated supply","right":"Taxable supply charged at 0% where legal requirements are met."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What makes a filing system effective for bookkeeping?”, the proposed answer is “It deletes old files automatically every month”.","answer":false,"feedback":"Retrieval and traceability are central to good record control."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is an authoritative record?”, the proposed answer is “A document that never needs retention review”.","answer":false,"feedback":"Defining the authoritative copy reduces uncertainty and uncontrolled duplication."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Which statement best reflects POPIA-aligned retention?”, the proposed answer is “Personal information should not be retained longer than authorised or necessary, subject to legal, contractual and lawful exceptions”.","answer":true,"feedback":"POPIA limits unnecessary retention while allowing legally or lawfully required retention."},{"id":"q4","answer":0,"prompt":"Why can a legal hold affect normal disposal?","options":["It requires relevant records to be preserved despite the ordinary retention schedule","It applies only to paper documents","It allows affected records to be destroyed once the ordinary retention date has passed, even when they remain relevant to the legal hold","It removes confidentiality obligations"],"feedback":"A hold preserves relevant evidence while a dispute, audit, investigation or legal requirement remains active.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Audit trail","right":"Traceable path connecting source evidence, approvals and accounting entries."},{"left":"Indexing","right":"Organising records using consistent identifiers so they can be retrieved."},{"left":"Retention","right":"Keeping records for the required period under applicable law and organisational policy."},{"left":"Disposition","right":"Approved final action when a record reaches the end of its retention period."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(2, 8, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"What should happen before an item is coded in the practical batch?","options":["Check the evidence and determine the economic substance","Select the first account suggested by software","Wait until the annual financial statements are complete","Post everything to Suspense permanently"],"feedback":"Coding should follow evidence and transaction analysis.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Two PDF invoices have the same supplier, invoice number, date and amount. What should the bookkeeper do?”, the proposed answer is “Investigate whether one is a duplicate copy before creating another liability”.","answer":true,"feedback":"Duplicate-looking evidence should be investigated before capture."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A confirmed customer EFT settles an existing debtor balance. What is the basic entry?”, the proposed answer is “Debit Bank; Credit Accounts Receivable”.","answer":true,"feedback":"The receipt increases Bank and reduces the existing receivable."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A missing approval remains unresolved at period end. Where should it be recorded for controlled follow-up?”, the proposed answer is “To record only completed transactions”.","answer":false,"feedback":"An exception register keeps unclear items visible and accountable."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Document batch","right":"Group of source documents processed together."},{"left":"Exception","right":"Item that does not meet the normal processing rule and requires investigation or escalation."},{"left":"Coding","right":"Selecting the appropriate ledger account and tax code for a transaction."},{"left":"Matched transaction","right":"Transaction linked to sufficient relevant supporting evidence."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(3, 1, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “An authorised non-routine correction needs debits, credits, a narration and supporting evidence before posting. Which record is appropriate?”, the proposed answer is “To organise the debit-and-credit effect of transactions before or as they move into ledger accounts”.","answer":true,"feedback":"A journal organises transaction effects chronologically. It does not replace evidence or prove that the treatment is correct."},{"id":"q2","answer":2,"prompt":"Which transaction is most likely to belong in a routine sales module rather than a general journal?","options":["An authorised opening-balance correction","An approved depreciation adjustment","A customer credit-sale invoice","A reclassification between two expense accounts"],"feedback":"Routine customer invoices should normally use the customer or sales process where available so subsidiary records update correctly.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What must always be true of a complete journal entry?”, the proposed answer is “Total debits must equal total credits”.","answer":true,"feedback":"A journal may affect several accounts, but total debits and total credits must be equal."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why is a meaningful journal narration important?”, the proposed answer is “It allows supporting evidence to be discarded”.","answer":false,"feedback":"Narration helps a reviewer understand why the journal exists and where supporting evidence can be found."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Journal","right":"Chronological accounting record in which transactions are first recorded or grouped before posting to ledger accounts."},{"left":"Special journal","right":"Journal designed for recurring transaction types, such as sales, purchases or cash receipts."},{"left":"General journal","right":"Journal commonly used for non-routine entries, corrections and adjustments."},{"left":"Narration","right":"Brief explanation of why a journal entry was made."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(3, 2, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the main difference between a journal and the general ledger?”, the proposed answer is “A journal groups information by account while the ledger only shows dates”.","answer":false,"feedback":"Journals organise transactions in chronological or transaction streams; ledger accounts accumulate the effects by account."},{"id":"q2","answer":3,"prompt":"Which side of a T-account is the debit side?","options":["Either side depending on the account","Top","Right","Left"],"feedback":"Debit is the left side of a T-account; credit is the right side.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Bank opens at R20,000 debit, receives R5,000 and pays R7,500. What is the closing balance?”, the proposed answer is “R17,500 credit”.","answer":false,"feedback":"R20,000 + R5,000 - R7,500 = R17,500 debit."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is balance carried down in a traditional manual ledger?”, the proposed answer is “An amount that must always be credited to income”.","answer":false,"feedback":"Balance c/d is a manual balancing presentation, not a new economic transaction."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"General ledger","right":"Collection of accounts summarising the financial effects of transactions."},{"left":"T-account","right":"Simple account diagram with debits on the left and credits on the right."},{"left":"Opening balance","right":"Balance brought forward from a previous period."},{"left":"Closing balance","right":"Balance after all recorded movements for the period."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(3, 3, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “The sales-journal total is transferred to the relevant general-ledger accounts. What step is being performed?”, the proposed answer is “Preparing a bank reconciliation”.","answer":false,"feedback":"Posting transfers the debit and credit effects into the relevant ledger accounts."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why is a posting reference useful?”, the proposed answer is “It proves the transaction is tax deductible”.","answer":false,"feedback":"References preserve traceability between journals, ledger postings and supporting records."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A batch control total is R42,000 but the ledger movement is R41,200. What should the bookkeeper do?”, the proposed answer is “Ignore the R800 difference”.","answer":false,"feedback":"A control-total difference is an exception requiring investigation, not an unexplained balancing entry."},{"id":"q4","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Posting","right":"Transferring journal information to ledger accounts."},{"left":"Posting reference","right":"Cross-reference linking journal and ledger records."},{"left":"Batch","right":"Group of transactions processed together."},{"left":"Control total","right":"Independent total used to check completeness of processing."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."},{"id":"q5","answer":3,"prompt":"Why does automated posting still require review?","options":["Because every automated transaction is fraudulent","Because software cannot perform arithmetic","Because automated systems replace the general ledger with transaction lists and do not retain account balances for review","Because automation can repeatedly apply incorrect mappings or dates"],"feedback":"Automation can repeat configuration or mapping errors quickly, so controls and review remain necessary.","type":"mcq"}]}'),
(3, 4, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"Which account types normally carry debit balances?","options":["Liabilities and income","Assets and expenses","Liabilities and equity","Equity and income"],"feedback":"Assets and expenses normally carry debit balances; liabilities, equity and income normally carry credit balances.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Creditors opens at R8,000 credit, new invoices are R2,500 credit and payments are R6,000 debit. What is the closing balance?”, the proposed answer is “R4,500 credit”.","answer":true,"feedback":"R8,000 + R2,500 - R6,000 = R4,500 credit."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Does an unusual account balance automatically prove an error?”, the proposed answer is “No; it should be investigated because legitimate explanations may exist”.","answer":true,"feedback":"Unusual balances are useful warning signals, but the cause must be confirmed from evidence."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Which statement best describes a contra account?”, the proposed answer is “It is designed to offset a related account and normally carries the opposite balance direction”.","answer":true,"feedback":"Contra accounts intentionally offset related balances, so their normal direction can differ from the related account."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Normal balance","right":"Side on which an account type generally carries a positive balance."},{"left":"Debit balance","right":"Account balance where debit movements exceed credit movements."},{"left":"Credit balance","right":"Account balance where credit movements exceed debit movements."},{"left":"Balance c/d","right":"Balance carried down to close a traditional ledger account."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(3, 5, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What does a trial balance primarily test?”, the proposed answer is “Whether every transaction is legally valid”.","answer":false,"feedback":"The trial balance tests arithmetic equality of debit and credit ledger balances."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “The ledger shows Equipment R8,000 debit but the trial balance shows R8,800 debit. What should be checked first?”, the proposed answer is “Move R800 to suspense immediately”.","answer":false,"feedback":"If the ledger is correct, the error is in extraction and should be corrected in the trial balance, not through a ledger journal."},{"id":"q3","answer":0,"prompt":"Can a completely omitted transaction leave a trial balance balanced?","options":["Yes, because both debit and credit sides may be missing","No, omission always creates a difference","Only at year end","Only if it involves cash"],"feedback":"A complete omission removes both sides equally, so the trial balance may still balance.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is a suspense account intended to be when used appropriately?”, the proposed answer is “A temporary controlled account while an issue is investigated”.","answer":true,"feedback":"Suspense should be temporary, supported and actively resolved rather than used to hide unexplained balances."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Trial balance","right":"List of ledger balances split into debit and credit columns."},{"left":"Debit column","right":"Column containing accounts with debit balances."},{"left":"Credit column","right":"Column containing accounts with credit balances."},{"left":"Extraction error","right":"Error when transferring balances from the ledger to the trial balance."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(3, 6, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"Can a completely omitted supplier invoice leave the trial balance balanced?","options":["Yes, because both the debit and credit are missing","Only if it has VAT","Only if it is paid","No, omissions always create a difference"],"feedback":"When both sides are omitted, debit-credit equality can remain even though the accounts are incomplete.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Equipment is posted to Repairs Expense but Bank is credited correctly. What type of problem is this?”, the proposed answer is “A bank reconciliation only”.","answer":false,"feedback":"The amount may be balanced, but the wrong accounting category has been used."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why can a payment posted to the wrong supplier escape the trial balance?”, the proposed answer is “Because the general-ledger control total can remain correct while subsidiary detail is wrong”.","answer":true,"feedback":"Wrong-supplier allocations can leave the control total unchanged while individual supplier balances are incorrect."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should a correction record preserve?”, the proposed answer is “The original reference, nature of the error, correcting action and required approval”.","answer":true,"feedback":"A traceable correction explains what was wrong, how it was fixed and who authorised or reviewed the change where required."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Error of omission","right":"Transaction not recorded, or one required part omitted."},{"left":"Error of commission","right":"Entry made to the wrong account of the same general type or wrong subsidiary account."},{"left":"Error of principle","right":"Transaction classified against an inappropriate accounting principle/category, such as treating an asset as an ordinary expense."},{"left":"Transposition error","right":"Digits reversed, such as 64 entered as 46."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(3, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Why is Debtors Control maintained in the general ledger while individual customer balances remain in the subledger?”, the proposed answer is “To replace all customer and supplier records”.","answer":false,"feedback":"A control account summarises the related subsidiary ledger while detailed customer or supplier records remain available separately."},{"id":"q2","answer":0,"prompt":"What should the total of individual customer balances reconcile to?","options":["Debtors Control","Bank only","Creditors Control","Sales only"],"feedback":"Customer subsidiary balances should reconcile to Debtors Control at the same cut-off date.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why must a control-account reconciliation use the same cut-off date for both records?”, the proposed answer is “To avoid artificial timing differences”.","answer":true,"feedback":"Using different dates can create differences caused by transactions occurring between the two cut-offs."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why can direct journals to a control account be risky?”, the proposed answer is “They make every supplier balance zero”.","answer":false,"feedback":"A direct control-account journal can break agreement with customer or supplier detail unless the process also handles the subsidiary records."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Control account","right":"General-ledger summary account representing a group of detailed subsidiary balances."},{"left":"Subsidiary ledger","right":"Detailed records supporting a control account, such as customer or supplier accounts."},{"left":"Debtors control","right":"General-ledger summary of amounts receivable from customers."},{"left":"Creditors control","right":"General-ledger summary of amounts owed to suppliers."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(3, 8, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the first step before preparing journal entries in an integrated practical?”, the proposed answer is “Analyse the transaction and supporting evidence”.","answer":true,"feedback":"Transaction analysis and evidence come before journal preparation."},{"id":"q2","answer":1,"prompt":"In the main scenario, what is the closing Bank balance?","options":["R20,000 debit","R24,000 debit","R30,000 debit","R24,000 credit"],"feedback":"R20,000 + R5,000 - R3,000 - R4,000 + R6,000 = R24,000 debit.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What are the total debits and credits in the main trial balance?”, the proposed answer is “R44,500”.","answer":false,"feedback":"Both debit and credit columns total R48,500."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Bank is correctly R24,000 in the ledger but was copied as R24,900 to the trial balance. Should a R900 ledger journal be posted?”, the proposed answer is “No; correct the extraction because no R900 transaction occurred”.","answer":true,"feedback":"The ledger is already correct. Posting a journal would create an accounting error."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Source document","right":"Evidence that supports the transaction before it is recorded."},{"left":"Journal","right":"A chronological record used to organise transaction entries before ledger posting."},{"left":"Ledger","right":"The collection of accounts in which transaction effects and balances accumulate."},{"left":"Trial balance","right":"A list of ledger balances used to test equality of total debits and credits."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 1, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"A customer pays R6,000 against an invoice that was recorded earlier. Which treatment is normally appropriate?","options":["Debit Debtors and credit Bank","Debit Sales and credit Bank","Debit Bank and credit a random income account","Debit Bank and credit Debtors"],"feedback":"The receipt increases Bank and reduces the existing customer receivable. It does not create a second sale.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why should an unexplained bank deposit not automatically be posted to Sales?”, the proposed answer is “Because the source and purpose of the receipt must be established before classification”.","answer":true,"feedback":"A deposit can arise from many sources. The bookkeeper should investigate and classify it from evidence rather than assumption."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the correct principle for a transfer between two business bank accounts?”, the proposed answer is “Record income in the receiving account and an expense in the paying account”.","answer":false,"feedback":"An internal transfer changes where the business holds cash. It does not by itself create income or expense."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the main purpose of a cashbook reference?”, the proposed answer is “To link the recorded transaction to supporting evidence and related records”.","answer":true,"feedback":"A meaningful reference strengthens traceability between the cashbook entry and the evidence supporting it."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Cashbook","right":"Accounting record used to capture cash and bank receipts and payments."},{"left":"Cash receipt","right":"Money received by the business."},{"left":"Cash payment","right":"Money paid by the business."},{"left":"Bank column","right":"Cashbook column used for bank-account movements."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 2, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “A supplier invoice was already captured as an expense and creditor. What is the normal effect when the supplier is later paid by EFT?”, the proposed answer is “Increase the creditor balance”.","answer":false,"feedback":"The original invoice created the expense or asset and creditor. Paying the supplier settles the liability rather than creating the expense a second time."},{"id":"q2","answer":0,"prompt":"Why can a card settlement deposited to the bank be lower than the gross card sales?","options":["Because merchant or processor fees may be deducted before settlement","Because the customer invoice disappears","Because all card sales are loans","Because sales must always be reduced to the bank amount"],"feedback":"Processor or merchant fees can create a gross-to-net difference that should be explained separately from sales.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What should happen when an EFT already captured manually appears later through the bank feed?”, the proposed answer is “Capture it again to ensure completeness”.","answer":false,"feedback":"Matching prevents the same payment from being recorded twice."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the best response to changed supplier banking details received in an urgent email?”, the proposed answer is “Pay immediately because the invoice is genuine”.","answer":false,"feedback":"A genuine invoice does not prove that newly supplied bank details are genuine. Independent verification reduces payment-diversion risk."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"EFT","right":"Electronic funds transfer between bank accounts."},{"left":"Debit order","right":"Authorised recurring or once-off collection initiated against a bank account."},{"left":"Card transaction","right":"Payment processed through debit or credit card infrastructure."},{"left":"Bank feed","right":"Electronic import of banking transactions into accounting software."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 3, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the main idea of an imprest petty-cash system?”, the proposed answer is “The fund is restored to an approved amount after valid spending is reconciled”.","answer":true,"feedback":"An imprest system maintains an approved float and restores it after validated expenditure has been reconciled."},{"id":"q2","answer":0,"prompt":"A R2,000 float has R650 cash and R1,300 of valid vouchers. What does the reconciliation show?","options":["There is a R50 shortage","The fund is fully reconciled","There is a R50 overage","The replenishment must be R2,000"],"feedback":"R650 + R1,300 = R1,950, which is R50 less than the R2,000 approved float.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What should happen if a receipt supporting petty-cash spending is missing?”, the proposed answer is “Increase another voucher to compensate”.","answer":false,"feedback":"Missing evidence should be dealt with transparently through the approved exception process. Evidence should never be fabricated."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why are surprise petty-cash counts useful?”, the proposed answer is “They independently test whether cash and supporting evidence actually exist”.","answer":true,"feedback":"Unannounced counts strengthen control by verifying the physical cash and evidence without advance preparation."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Petty cash","right":"Small controlled cash fund for minor approved expenses."},{"left":"Imprest system","right":"System in which the petty-cash float is restored to an approved fixed amount after valid spending is reconciled."},{"left":"Petty-cash voucher","right":"Record supporting money issued from the fund."},{"left":"Float","right":"Approved amount maintained in petty cash."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 4, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should happen first when an EFT on the bank statement already exists correctly in the cashbook?”, the proposed answer is “Match it to the existing cashbook entry”.","answer":true,"feedback":"A statement line representing an existing transaction should be matched, not duplicated."},{"id":"q2","answer":3,"prompt":"Which item most clearly belongs in the cashbook before the bank reconciliation if it is valid and not yet recorded?","options":["An outstanding EFT already recorded in the books","A deposit in transit already recorded in the books","A payment the bank has not yet processed","A bank charge appearing on the statement for the first time"],"feedback":"A valid bank charge missing from the books is a book-side item and should normally be recorded before reconciliation.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the correct treatment of a valid payment already recorded in the cashbook but not yet processed by the bank at cut-off?”, the proposed answer is “Delete it from the cashbook”.","answer":false,"feedback":"The cashbook is already correct. The delay in bank processing creates a timing difference rather than a second bookkeeping entry."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should an unidentified direct deposit not be allocated to a customer without evidence?”, the proposed answer is “Because the payer and purpose must be established before allocation”.","answer":true,"feedback":"Correct allocation depends on evidence identifying the payer and purpose of the receipt."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Bank statement","right":"Bank''s record of transactions and balance for an account."},{"left":"Book balance","right":"Balance according to the business cashbook or bank ledger."},{"left":"Bank-originated item","right":"Transaction first identified from the bank statement, such as charges or interest."},{"left":"Direct deposit","right":"Money deposited directly into the account, potentially before the business identifies the payer."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 5, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the main purpose of a bank reconciliation?”, the proposed answer is “To explain and verify the difference between the updated books and the bank statement”.","answer":true,"feedback":"A bank reconciliation explains the relationship between the book and bank records at a specific date."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A deposit recorded in the cashbook on 30 June appears on the bank statement on 1 July. How is the item classified in the June reconciliation?”, the proposed answer is “A receipt recorded by the business but not yet reflected by the bank at cut-off”.","answer":true,"feedback":"A deposit in transit is a timing difference: the business has recorded the receipt but the bank has not yet reflected it by cut-off."},{"id":"q3","answer":3,"prompt":"Starting from a positive bank-statement balance, how is an outstanding payment commonly treated in the reconciliation?","options":["Added","Posted again to the cashbook","Ignored permanently","Subtracted"],"feedback":"The books have already reduced for the payment while the bank has not, so the outstanding payment is commonly subtracted from the statement balance in this format.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen if a cashbook error is discovered during reconciliation?”, the proposed answer is “Leave it forever as a reconciling item”.","answer":false,"feedback":"A genuine book error belongs in the books and should be corrected from evidence rather than carried as a permanent timing item."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Bank reconciliation","right":"Comparison explaining the difference between book and bank-statement balances at a date."},{"left":"Outstanding payment","right":"Payment recorded by the business but not yet processed by the bank."},{"left":"Deposit in transit","right":"Receipt recorded by the business but not yet reflected by the bank."},{"left":"Reconciling item","right":"Valid item explaining a temporary difference between records."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 6, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the first step when a bank-reconciliation item is unmatched?”, the proposed answer is “Classify the type of difference before deciding what to do”.","answer":true,"feedback":"Classifying the difference helps separate timing, book errors, possible bank errors and unresolved exceptions before any correction is made."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A supplier EFT appears twice in the cashbook but once on the bank statement. What should the bookkeeper do?”, the proposed answer is “Add a second bank-statement line”.","answer":false,"feedback":"If evidence confirms one real payment and two book entries, the duplicate belongs to the business records and should be corrected through the authorised process."},{"id":"q3","answer":1,"prompt":"Should an unidentified customer deposit be posted to Sales automatically?","options":["Yes, because a small unidentified deposit is presumed to be sales revenue unless a customer later disputes it","No, the payer and purpose should be investigated first","Yes","Only if the reconciliation is late"],"feedback":"An unidentified receipt can represent many different transactions. Classification should be based on evidence.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why is exception ageing useful?”, the proposed answer is “It shows how long unresolved items remain open and helps prioritise follow-up”.","answer":true,"feedback":"Ageing makes persistent unresolved items visible so they receive appropriate attention."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Unmatched item","right":"Transaction appearing in one record but not yet matched in the other."},{"left":"Timing difference","right":"Valid transaction recorded at different times by the business and bank."},{"left":"Book error","right":"Error in the business accounting records."},{"left":"Bank error","right":"Error originating in the bank''s records."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the main purpose of segregation of duties?”, the proposed answer is “To eliminate the need for management review”.","answer":false,"feedback":"Separating incompatible responsibilities makes errors and misuse harder to carry out and conceal."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A customer says R20,000 will be paid later today. How should it appear in a morning cash-position report?”, the proposed answer is “It should be ignored forever”.","answer":false,"feedback":"Expected receipts should be distinguished from confirmed balances so management does not mistake a forecast for available cash."},{"id":"q3","answer":0,"prompt":"Why can a high bank balance still leave a business with little free cash?","options":["Because some funds may already be committed or restricted","Because receipts are always expenses","Because every scheduled payment must be cancelled before management may regard any part of the bank balance as available","Because bank balances are never reliable"],"feedback":"Available cash should be considered together with commitments and restrictions, not from the headline bank balance alone.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Which item is a banking red flag requiring further review?”, the proposed answer is “An urgent request to bypass approval and pay changed supplier bank details”.","answer":true,"feedback":"Urgency combined with changed bank details and a request to bypass normal controls is a strong reason for independent verification and escalation."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Cash position","right":"Current view of available cash and bank balances."},{"left":"Available funds","right":"Funds currently available for authorised use, subject to restrictions and commitments."},{"left":"Committed payment","right":"Payment already approved or expected to be made."},{"left":"Segregation of duties","right":"Separation of incompatible responsibilities to reduce error or misuse."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(4, 8, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"Which item should normally be recorded in the cashbook before bank reconciliation if it is valid and not yet captured?","options":["A bank charge appearing on the statement for the first time","A timing difference that has already been correctly recorded","An outstanding EFT already recorded in the cashbook","A deposit in transit already recorded in the cashbook"],"feedback":"A valid bank charge missing from the books is a book-side item and should normally be recorded before reconciliation.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why is a deposit in transit not captured again in the cashbook during reconciliation?”, the proposed answer is “Because it is already correctly recorded in the books and the difference is only bank timing”.","answer":true,"feedback":"The cashbook already contains the receipt. Recording it again would duplicate the transaction."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “In the Khula Office Services example, what is the updated cashbook balance?”, the proposed answer is “R44,720”.","answer":true,"feedback":"R42,500 - R250 + R100 - R1,200 + R3,500 + R70 = R44,720."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen if a reconciliation still differs after all known items are included?”, the proposed answer is “Post a miscellaneous expense to force agreement”.","answer":false,"feedback":"An unresolved difference must remain visible and be investigated. A balancing journal without evidence would hide the real cause."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Cashbook","right":"The entity’s record of bank and cash receipts and payments."},{"left":"Bank statement","right":"The bank’s record of movements and balances on the account."},{"left":"Deposit in transit","right":"A receipt recorded by the entity but not yet reflected by the bank."},{"left":"Unpresented payment","right":"A payment recorded by the entity but not yet processed by the bank."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 1, '{"version":2,"questions":[{"id":"q1","answer":2,"prompt":"What normally creates a customer receivable?","options":["A supplier payment","A bank reconciliation only","A credit sale or other valid amount billed to a customer","A transfer between business bank accounts"],"feedback":"A receivable arises when the customer owes the business, commonly after a valid credit sale or charge.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A customer pays an invoice that was already recorded. What is the normal effect?”, the proposed answer is “Increase Bank and reduce the customer receivable”.","answer":true,"feedback":"The receipt settles an existing receivable; it does not create the sale again."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why must individual customer balances be reviewed even when Debtors Control agrees to the customer-listing total?”, the proposed answer is “Because every customer should have the same balance”.","answer":false,"feedback":"A wrong customer allocation can preserve the total while mis-stating individual accounts."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen when a supplier invoice cannot yet be linked confidently to the correct supplier record?”, the proposed answer is “Investigate the evidence and keep the item controlled until the correct allocation is supported”.","answer":true,"feedback":"Party-level allocation should be evidence-based; guessing creates duplicate and payment risks."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Debtor / Accounts Receivable","right":"Customer who owes the business money."},{"left":"Creditor / Accounts Payable","right":"Supplier to whom the business owes money."},{"left":"Credit sale","right":"Sale where payment will be received later."},{"left":"Credit purchase","right":"Purchase where payment will be made later."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 2, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should normally trigger customer billing?”, the proposed answer is “The desire to increase month-end sales”.","answer":false,"feedback":"Billing should be supported by the underlying supply, contract or authorised business event."},{"id":"q2","answer":1,"prompt":"At South Africa''s current 15% VAT rate, what VAT is included in R11,500 of standard-rated VAT-inclusive consideration?","options":["R1,000","R1,500","R1,725","R10,000"],"feedback":"R11,500 × 15/115 = R1,500, leaving R10,000 VAT exclusive.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Under current SARS VAT guidance, which statement correctly describes when a full tax invoice is required?”, the proposed answer is “For consideration of R5,000 or more, and also for zero-rated supplies even below R5,000”.","answer":true,"feedback":"Current SARS VAT guidance requires a full tax invoice where consideration is R5,000 or more, and also for zero-rated supplies even when consideration is below R5,000."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should cancelled or voided invoice numbers remain traceable?”, the proposed answer is “So the same number can be reused quietly”.","answer":false,"feedback":"Traceable voids help explain gaps and detect duplicates or unauthorised deletion."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Sales invoice","right":"Document issued to a customer for goods or services supplied."},{"left":"Invoice number","right":"Unique reference identifying the invoice."},{"left":"Credit note","right":"Document reducing or reversing an amount previously invoiced."},{"left":"Customer account","right":"Subsidiary record showing invoices, receipts, credits and balance for one customer."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 3, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the normal accounting effect when a customer pays an invoice already recorded?”, the proposed answer is “Increase a supplier balance”.","answer":false,"feedback":"The receipt settles an existing customer balance and should not create the sale again."},{"id":"q2","answer":3,"prompt":"A R10,000 invoice receives a R6,000 part-payment. What should normally remain open?","options":["R6,000","R10,000","Nothing","R4,000"],"feedback":"Unless an authorised adjustment exists, the unpaid R4,000 remains outstanding.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the safest treatment of an unidentified bank receipt?”, the proposed answer is “Investigate and use the approved unidentified or unapplied-cash process until supported”.","answer":true,"feedback":"Classification should follow evidence; an unidentified receipt should remain visible and controlled."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should a customer credit balance be investigated before refund?”, the proposed answer is “Because it may represent an overpayment, advance, other invoice allocation or duplicate payment”.","answer":true,"feedback":"The cause of the credit must be established so the business does not refund money incorrectly."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Receipt allocation","right":"Matching money received to the correct customer and invoice(s)."},{"left":"Remittance advice","right":"Information supplied by a customer explaining which invoices a payment covers."},{"left":"Part-payment","right":"Payment covering only part of an outstanding amount."},{"left":"Unallocated receipt","right":"Receipt whose customer or invoice has not yet been confirmed."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 4, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"A supplier invoice was already recorded as an expense and payable. What is the normal effect when it is later paid?","options":["Increase Sales","Increase the payable","Record the expense again","Reduce the payable and reduce Bank"],"feedback":"Payment settles the existing liability; it does not create the expense again.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What should happen if a supplier statement contains an invoice missing from the books?”, the proposed answer is “Pay it immediately from the statement”.","answer":false,"feedback":"The statement identifies a difference, but the underlying obligation should be verified from appropriate source evidence."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why should duplicate-invoice checks compare more than the invoice number?”, the proposed answer is “Because invoice numbers are never useful”.","answer":false,"feedback":"Supplier, amount, date, purchase evidence and invoice reference together provide stronger duplicate detection."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the purpose of supplier remittance information?”, the proposed answer is “To explain which invoices or credits the payment settles”.","answer":true,"feedback":"Clear remittance helps the supplier allocate the payment correctly and reduces statement differences."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Supplier invoice","right":"Document requesting payment for goods or services supplied."},{"left":"Creditor account","right":"Record of amounts owed to a supplier."},{"left":"Supplier statement","right":"Supplier''s summary of invoices, credits, payments and balance."},{"left":"Remittance advice","right":"Information sent with payment explaining which items are being settled."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 5, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should happen before management relies on a debtor age analysis?”, the proposed answer is “The receivables control total and individual customer listing should be reconciled”.","answer":true,"feedback":"Ageing is only useful when the underlying customer balances are reliable and reconciled."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why does the ageing method matter?”, the proposed answer is “Because invoice-date and due-date ageing can classify the same invoice differently”.","answer":true,"feedback":"The configured ageing basis and payment terms determine whether an amount is truly past due."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A customer balance is 90+ days old. What can you safely conclude?”, the proposed answer is “It requires investigation, but age alone does not prove the cause or recoverability”.","answer":true,"feedback":"Old balances can arise from non-payment, disputes, missing credits, allocation errors or other causes."},{"id":"q4","answer":0,"prompt":"Which item most clearly belongs on a debtor exception report?","options":["A 90+ day balance with repeated broken promises","A matched receipt with no issue","A fully settled account","A normal current invoice within terms"],"feedback":"Age, value and broken promises make the balance a clear follow-up exception.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Debtors reconciliation","right":"Comparison of Debtors Control with individual customer balances and supporting records."},{"left":"Age analysis","right":"Report grouping receivables according to how long they have been outstanding."},{"left":"Current","right":"Amount not yet overdue according to agreed terms/report logic."},{"left":"Overdue","right":"Amount beyond its payment due date."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 6, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should normally happen before a supplier payment proposal is finalised?”, the proposed answer is “All statement totals should be paid blindly”.","answer":false,"feedback":"Payment preparation should start from reconciled, supported obligations."},{"id":"q2","answer":1,"prompt":"A supplier has R24,000 of gross open invoices before applying a valid R3,000 credit note, and R5,000 of those invoices is on dispute hold. What preliminary net amount remains if only the undisputed amount is considered?","options":["R8,000","R16,000","R21,000","R24,000"],"feedback":"R24,000 − R3,000 − R5,000 = R16,000 before final approval and other payment criteria.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the correct response to newly changed supplier banking details?”, the proposed answer is “Pay immediately if the email looks genuine”.","answer":false,"feedback":"Changed bank details are a payment-diversion risk and require independent verification."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why is payment release status different from payment approval status?”, the proposed answer is “Approval means the bank has definitely processed the payment”.","answer":false,"feedback":"Approval, release and clearing are different stages and should be tracked separately."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Creditors reconciliation","right":"Comparison of Creditors Control with individual supplier balances."},{"left":"Payment run","right":"Group of supplier payments prepared for approval/release."},{"left":"Due date","right":"Date payment is contractually or operationally expected."},{"left":"Payment schedule","right":"List of proposed payments with amounts, references and approval information."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should happen before a customer is chased for an overdue balance?”, the proposed answer is “Confirm that the customer account is accurate and reconciled”.","answer":true,"feedback":"Collection should start from reliable invoices, receipts, credits and dispute status."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What information should a useful promise-to-pay record contain?”, the proposed answer is “Only the original invoice number”.","answer":false,"feedback":"A precise promise record allows the business to monitor whether the commitment was actually met."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “How should a genuinely disputed portion of a customer balance be handled?”, the proposed answer is “Threaten legal action immediately”.","answer":false,"feedback":"A dispute requires evidence and authorised resolution while remaining traceable on the account."},{"id":"q4","answer":2,"prompt":"Can a bookkeeper normally increase a customer''s credit limit because the customer asks?","options":["Yes, if the customer is large","Yes, always","No, unless that authority has been formally delegated","Yes, if the account is overdue and a higher credit limit would allow the customer to place another order"],"feedback":"Credit-limit decisions are controlled commercial decisions requiring appropriate authority.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Credit control","right":"Processes used to manage customer credit and collect amounts due."},{"left":"Collection follow-up","right":"Contact or action seeking payment of overdue balances."},{"left":"Promise to pay","right":"Customer commitment to pay a stated amount by a stated date."},{"left":"Credit limit","right":"Approved maximum customer exposure."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(5, 8, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"What is the closing receivables balance in the main practical?","options":["R40,000","R48,000","R30,000","R36,000"],"feedback":"R40,000 + R8,000 − R7,000 − R2,000 − R3,000 = R36,000.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the closing payables balance before the R2,500 supplier-statement exception is verified?”, the proposed answer is “R23,500”.","answer":false,"feedback":"R30,000 + R6,000 − R1,000 − R4,000 − R10,000 = R21,000."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “A R2,000 receipt is included in Debtors Control but allocated to the wrong customer. What does agreement of the control total demonstrate?”, the proposed answer is “Only if the bank statement is wrong”.","answer":false,"feedback":"Allocation errors can hide inside a correct control total, which is why subsidiary review matters."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen when a supplier statement shows an invoice missing from the books?”, the proposed answer is “Change the ledger to match the statement with no evidence”.","answer":false,"feedback":"A statement identifies a difference; the underlying supplier obligation must still be supported."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Debtors Control","right":"The general-ledger total of amounts owed by customers."},{"left":"Creditors Control","right":"The general-ledger total of amounts owed to suppliers."},{"left":"Age analysis","right":"A report grouping outstanding balances by how long they have been unpaid."},{"left":"Control-account reconciliation","right":"A comparison of a control balance with its supporting subledger schedule."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(6, 1, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the strongest reason for posting a period-end adjustment?”, the proposed answer is “To align the accounts with the correct period, evidence and approved accounting treatment”.","answer":true,"feedback":"Adjustments are about period-correct, supportable accounting—not target results."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Which item is the best evidence base for an unbilled service accrual?”, the proposed answer is “A prior journal with no explanation”.","answer":false,"feedback":"An estimate should have a documented and reasonable basis."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Does a balanced adjusting journal prove the adjustment is correct?”, the proposed answer is “No; amount, period, classification, evidence and authority still require review”.","answer":true,"feedback":"Arithmetic equality is necessary but not sufficient."},{"id":"q4","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Period end","right":"Cut-off date for an accounting reporting period."},{"left":"Adjustment","right":"Entry made to correct timing, valuation or classification before reporting."},{"left":"Accrual basis","right":"Accounting approach that recognises income and expenses when earned/incurred rather than only when cash moves."},{"left":"Cut-off","right":"Ensuring transactions are recorded in the correct period."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."},{"id":"q5","answer":0,"prompt":"What should happen to an unresolved period-end item with inadequate evidence?","options":["Document and escalate it as an exception","Create a fictitious supplier invoice","Post it to miscellaneous expense","Ignore it permanently"],"feedback":"Unresolved items need investigation and escalation, not fabricated entries.","type":"mcq"}]}'),
(6, 2, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Which statement best describes an accrued expense?”, the proposed answer is “Cash paid for a future-period benefit”.","answer":false,"feedback":"An accrual recognises a current-period cost before the final invoice is recorded."},{"id":"q2","answer":1,"prompt":"Annual insurance of R24,000 covers 12 equal months and three months have been consumed. What is the remaining prepaid balance?","options":["R12,000","R18,000","R6,000","R24,000"],"feedback":"Nine months remain at R2,000 per month, so the prepaid balance is R18,000.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why should an accrual be compared with the later actual invoice?”, the proposed answer is “To identify and correctly treat any settlement variance”.","answer":true,"feedback":"The later invoice confirms the final amount and helps prevent double counting."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the strongest control over a prepayment balance?”, the proposed answer is “Reverse it every month regardless of service period”.","answer":false,"feedback":"A release schedule keeps the asset balance aligned with the remaining future benefit."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Accrual","right":"Expense incurred but not yet recorded or paid at period end."},{"left":"Prepayment","right":"Payment made in advance for a future period benefit."},{"left":"Accrued expense liability","right":"Amount recognised as owed for an expense already incurred."},{"left":"Prepaid expense asset","right":"Unused portion of a payment that relates to future periods."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(6, 3, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"What is the annual straight-line depreciation on an asset costing R60,000 with no residual value and a five-year useful life?","options":["R12,000","R10,000","R5,000","R15,000"],"feedback":"R60,000 ÷ 5 = R12,000 per year.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What does accumulated depreciation represent?”, the proposed answer is “The cash saved to replace an asset”.","answer":false,"feedback":"Accumulated depreciation tracks depreciation recognised over time."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why should a bookkeeper not invent a capitalisation threshold?”, the proposed answer is “Because thresholds are only used for tax”.","answer":false,"feedback":"Capitalisation decisions should follow policy and the applicable reporting framework."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “An asset cost R90,000 and accumulated depreciation is R30,000. What is the basic carrying amount?”, the proposed answer is “R60,000”.","answer":true,"feedback":"Carrying amount is R90,000 − R30,000 = R60,000, before any other applicable adjustments."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Fixed asset / Property, plant and equipment","right":"Long-term tangible resource used in the business."},{"left":"Depreciation","right":"Systematic allocation of a depreciable asset amount over its useful life."},{"left":"Useful life","right":"Period over which the asset is expected to provide benefit for accounting purposes."},{"left":"Residual value","right":"Estimated value remaining at the end of useful life, where applicable."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(6, 4, '{"version":2,"questions":[{"id":"q1","answer":2,"prompt":"Which situation by itself is only a warning indicator and does not justify writing off a receivable?","options":["The approved process confirms the specific receivable is irrecoverable","A completed recoverability review and authorised write-off conclude the specific balance is irrecoverable","The balance is 120 days overdue","Reliable insolvency evidence and the authorised review conclude recovery is not expected"],"feedback":"Age is a warning indicator, but allocation errors, disputes or payment arrangements may explain the balance.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the main difference between a specific write-off and a loss allowance?”, the proposed answer is “A write-off removes an identified irrecoverable balance; an allowance estimates expected losses on balances still recorded”.","answer":true,"feedback":"The two adjustments serve different purposes and should not be used interchangeably."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Gross receivables are R100,000, a R5,000 balance is written off, and a R3,000 allowance is recognised on the remainder. What is the net receivable amount, assuming no other adjustments?”, the proposed answer is “R100,000”.","answer":false,"feedback":"R100,000 − R5,000 − R3,000 = R92,000."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen if a previously written-off customer later pays?”, the proposed answer is “Record it without identifying the customer”.","answer":false,"feedback":"Recoveries should remain traceable to the earlier write-off."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Bad debt","right":"Receivable determined to be irrecoverable under the organisation''s approved process."},{"left":"Write-off","right":"Removal of a specific receivable balance from the books after appropriate approval."},{"left":"Allowance for doubtful debts / expected credit loss allowance","right":"Estimate reducing receivables for amounts that may not be collected, according to accounting policy."},{"left":"Recoverability","right":"Likelihood that a receivable will be collected."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(6, 5, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What makes an adjusted trial balance different from an unadjusted trial balance?”, the proposed answer is “It includes approved period-end adjustments that have been posted”.","answer":true,"feedback":"The adjusted trial balance reflects ledger balances after approved close adjustments."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Which control best helps confirm that approved closing journals were posted once and only once?”, the proposed answer is “A customer statement”.","answer":false,"feedback":"A closing journal register supports completeness, approval and posting traceability."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why should major balance-sheet accounts be reconciled before reporting?”, the proposed answer is “To confirm ledger balances agree to supporting records and schedules”.","answer":true,"feedback":"Reconciliations connect reported balances to detailed supporting records."},{"id":"q4","answer":3,"prompt":"Can a duplicated balanced journal leave the trial balance in balance?","options":["Only if it involves cash","Only if it is under R1,000","No","Yes"],"feedback":"A duplicate debit-and-credit entry can preserve arithmetic equality while misstating accounts.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Adjusted trial balance","right":"Trial balance after approved period-end adjustments."},{"left":"Closing check","right":"Review performed before reports are finalised."},{"left":"Suspense account","right":"Temporary account used under controlled circumstances for unresolved differences."},{"left":"Reconciliation status","right":"Evidence showing whether a balance agrees to supporting records."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(6, 6, '{"version":2,"questions":[{"id":"q1","answer":2,"prompt":"Sales are R500,000 and cost of sales is R300,000. What is gross profit?","options":["R300,000","R500,000","R200,000","R800,000"],"feedback":"Gross profit = sales less cost of sales = R200,000.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Which cash inflow creates a financing liability rather than revenue?”, the proposed answer is “Cash received from other recognised income”.","answer":false,"feedback":"Loan proceeds create a liability rather than revenue."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the effect of omitting a valid current-period expense accrual?”, the proposed answer is “Expenses are understated and profit overstated”.","answer":true,"feedback":"Missing a current-period expense causes reported profit to be too high."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why can depreciation reduce profit without reducing current-period cash?”, the proposed answer is “It allocates prior asset cost to the current period”.","answer":true,"feedback":"Depreciation is an accounting allocation, not a new cash payment."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Revenue / Income","right":"Amount earned from ordinary business activities or other recognised sources."},{"left":"Cost of sales","right":"Direct cost associated with goods or services sold, where applicable."},{"left":"Gross profit","right":"Revenue less cost of sales."},{"left":"Operating expense","right":"Cost of running the business, such as rent or administration."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(6, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What does the statement of financial position report?”, the proposed answer is “Only cash flows during a year”.","answer":false,"feedback":"The statement presents financial position at a specific reporting date."},{"id":"q2","answer":3,"prompt":"Equipment cost is R100,000 and accumulated depreciation is R30,000. What is the basic carrying amount?","options":["R130,000","R100,000","R30,000","R70,000"],"feedback":"R100,000 − R30,000 = R70,000.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why is liability completeness an important closing objective?”, the proposed answer is “It removes the need for supplier statements”.","answer":false,"feedback":"Unrecorded obligations can materially misstate both profit and financial position."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Which statement about current/non-current classification is most accurate?”, the proposed answer is “Classification follows the applicable reporting framework and can consider operating-cycle and contractual factors”.","answer":true,"feedback":"Classification requires the relevant framework and facts, not a universal shortcut."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Asset","right":"Resource controlled by the business expected to provide future economic benefit."},{"left":"Liability","right":"Present obligation of the business."},{"left":"Equity","right":"Owners'' residual interest after liabilities are deducted from assets."},{"left":"Current asset/liability","right":"Short-term classification determined by applicable reporting policy."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(6, 8, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"Sales increase from R300,000 to R360,000. What is the percentage increase?","options":["5%","20%","10%","60%"],"feedback":"The increase is R60,000 ÷ R300,000 = 20%.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Gross profit is R126,000 on sales of R360,000. What is the gross margin?”, the proposed answer is “30%”.","answer":false,"feedback":"R126,000 ÷ R360,000 = 35%."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Which statement is a fact rather than a hypothesis?”, the proposed answer is “Customers are definitely paying more slowly”.","answer":false,"feedback":"The balance movement is directly observable; the cause requires evidence."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Current assets are R200,000 and current liabilities are R150,000. What is basic working capital?”, the proposed answer is “R150,000”.","answer":false,"feedback":"Working capital = current assets − current liabilities = R50,000."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Variance","right":"Difference between two amounts, periods or expectations."},{"left":"Trend","right":"Direction or pattern in financial information over time."},{"left":"Working capital","right":"Broadly, current assets less current liabilities."},{"left":"Liquidity","right":"Ability to meet short-term obligations."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 1, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What does accounting software change most directly?”, the proposed answer is “The requirement for source evidence”.","answer":false,"feedback":"Software changes how users process bookkeeping, not the underlying accounting principles."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why can automation increase the impact of a configuration error?”, the proposed answer is “Because automated transactions do not use accounts”.","answer":false,"feedback":"A bad rule or mapping can be applied consistently across many transactions."},{"id":"q3","answer":2,"prompt":"A transaction balances but is posted to the wrong expense account. What type of problem is this?","options":["A missing debit","A missing credit","A classification error","A bank reconciliation difference only"],"feedback":"A complete debit and credit can still be posted to the wrong account.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why are individual user accounts preferable to shared logins?”, the proposed answer is “They improve attribution and permission control”.","answer":true,"feedback":"Individual accounts improve accountability and allow access to be aligned with responsibilities."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Computerised bookkeeping","right":"Recording and processing accounting information using software."},{"left":"Transaction module","right":"Software area for activities such as sales, purchases or banking."},{"left":"Audit trail","right":"System history showing transactions, users and changes."},{"left":"User role","right":"Access level defining what a person may view or change."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 2, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Where should opening balances come from?”, the proposed answer is “An approved reconciled source at the cutover date”.","answer":true,"feedback":"Opening balances should be supported by reconciled records and schedules."},{"id":"q2","answer":3,"prompt":"Why does account type matter in accounting software?","options":["It replaces source documents","It changes the legal name of the business","It guarantees the account will never need review","It can affect posting behaviour and report presentation"],"feedback":"The assigned account type helps determine how balances are handled and presented.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is a migration control total used for?”, the proposed answer is “To increase the migrated balance”.","answer":false,"feedback":"Control totals help prove that records or balances were transferred completely."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should test transactions be entered before go-live?”, the proposed answer is “To confirm workflows and mappings produce the expected accounting effect”.","answer":true,"feedback":"Controlled tests can expose setup errors before live transaction volume increases."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Company file","right":"Accounting-system environment containing the organisation''s financial records and settings."},{"left":"Chart of accounts","right":"Structured list of ledger accounts used for transaction classification."},{"left":"Account type","right":"Classification such as asset, liability, equity, income or expense."},{"left":"Opening date","right":"Date from which the system''s starting balances and transaction history are established."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 3, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"What is the main risk of duplicate supplier records?","options":["They can fragment history and increase duplicate-capture or payment risk","They prevent any invoices from being entered","They automatically close the supplier account","They make the supplier owe the business money automatically"],"feedback":"Duplicates split otherwise related transactions and weaken reconciliation.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What should opening customer detail reconcile to?”, the proposed answer is “The supplier ageing report”.","answer":false,"feedback":"Customer opening detail should tie back to the approved receivables source."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why can invoice-level opening detail be useful?”, the proposed answer is “It allows later receipts and ageing to be applied to the correct open items”.","answer":true,"feedback":"Open-item detail supports accurate allocation, ageing and statements."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “How should a supplier banking-detail change be controlled?”, the proposed answer is “Use independent verification and authorised change procedures”.","answer":true,"feedback":"Independent verification reduces the risk of redirecting payments."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Master record","right":"Core system record for a customer, supplier or other recurring entity."},{"left":"Opening receivable","right":"Amount a customer already owes when the new system begins."},{"left":"Opening payable","right":"Amount already owed to a supplier at migration date."},{"left":"Duplicate master","right":"More than one system record representing the same customer or supplier."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 4, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"An unpaid supplier invoice for office cleaning should normally create which balance?","options":["A customer receivable","A supplier payable","A bank deposit","An owner contribution"],"feedback":"An unpaid supplier bill creates an obligation to the supplier.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the safest response to a duplicate invoice warning?”, the proposed answer is “Investigate whether the transaction already exists”.","answer":true,"feedback":"Duplicate warnings should trigger evidence-based investigation."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why can a product/service item create repeated errors?”, the proposed answer is “Its mapping may be reused across many transactions”.","answer":true,"feedback":"Incorrect item mappings can repeatedly send transactions to the wrong account or tax treatment."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “A supplier bill has already recorded the expense. What should the later payment normally do?”, the proposed answer is “Reduce Accounts Payable and Bank”.","answer":true,"feedback":"The payment settles the payable; it should not duplicate the original expense."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Sales invoice screen","right":"Software workflow recording a customer credit sale."},{"left":"Supplier bill/purchase invoice","right":"Workflow recording a creditor obligation."},{"left":"Expense transaction","right":"Direct purchase/payment recorded without a creditor invoice workflow where appropriate."},{"left":"Tax code","right":"System setting controlling tax treatment of a line or transaction."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 5, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"What is the first question to ask when reviewing a downloaded bank transaction?","options":["Which expense account should I use?","Which report will hide it?","Can I delete the bank line?","Is this event already represented in the books?"],"feedback":"Matching existing records first helps prevent duplicate capture.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What does matching do?”, the proposed answer is “Creates a second accounting transaction”.","answer":false,"feedback":"Matching connects the downloaded movement to the existing transaction."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why should automated category suggestions be reviewed?”, the proposed answer is “Suggestions are accounting evidence”.","answer":false,"feedback":"Automation assists review but does not replace evidence or judgement."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the safest response to a reconciliation discrepancy that cannot be explained?”, the proposed answer is “Post a plug to miscellaneous expense”.","answer":false,"feedback":"A reconciliation should not be forced without evidence."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Bank feed","right":"Imported electronic stream of bank transactions."},{"left":"Match","right":"Linking an imported bank item to an existing accounting transaction."},{"left":"Add/Categorise","right":"Creating a new accounting transaction from an imported bank item where appropriate."},{"left":"Reconciliation screen","right":"Software workflow comparing book transactions to a bank statement."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 6, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Why can deleting a posted transaction be risky?”, the proposed answer is “It may destroy traceability or affect reconciliations and prior reports”.","answer":true,"feedback":"Deletion can remove evidence and change balances already relied upon."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Which correction method is always appropriate for every error?”, the proposed answer is “Manual journal”.","answer":false,"feedback":"Correction methods must fit the facts and system workflow."},{"id":"q3","answer":2,"prompt":"What is the main purpose of an activity log?","options":["To calculate VAT automatically","To replace source documents","To help trace system actions and changes","To guarantee no user can make an error"],"feedback":"Activity logs support investigation and accountability.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should permissions be role-based?”, the proposed answer is “To give every user administrator access”.","answer":false,"feedback":"Role-based access reduces unnecessary exposure to high-risk functions."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Edit","right":"Change to an existing transaction where the system and policy permit it."},{"left":"Void","right":"System action retaining a transaction record while cancelling its accounting effect, depending on software behaviour."},{"left":"Reversal","right":"Opposite accounting entry used to cancel a prior posting."},{"left":"Audit history","right":"System record of user activity and transaction changes."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 7, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"Why should report filters be checked before export?","options":["Filters are only used for payroll","Filters always increase profit","Filters remove the need for reconciliation","Old filters may exclude information unintentionally"],"feedback":"A leftover filter can make an otherwise valid report incomplete.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is a static export?”, the proposed answer is “A file snapshot that does not automatically change with later postings”.","answer":true,"feedback":"Exports are snapshots and can become outdated."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What should happen if a significant supporting reconciliation is incomplete?”, the proposed answer is “Call the report final anyway”.","answer":false,"feedback":"Users should know when figures may still change."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why is report provenance useful?”, the proposed answer is “It shows source, period and settings needed to understand the report”.","answer":true,"feedback":"Provenance helps reviewers understand exactly what the exported report represents."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Report parameter","right":"Setting such as date range, account, customer or basis controlling report output."},{"left":"Trial balance report","right":"List of ledger balances at a selected date or period."},{"left":"General ledger detail","right":"Transaction-level activity by account."},{"left":"Age analysis","right":"Customer or supplier balances grouped by age."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(7, 8, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"What is Customer A''s closing receivable after a R12,000 opening balance, an R8,000 credit sale and a R10,000 receipt?","options":["R2,000","R30,000","R20,000","R10,000"],"feedback":"R12,000 + R8,000 − R10,000 = R10,000.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Supplier X begins at R9,000 payable, receives a R4,500 bill and is paid R6,000. What is the closing payable?”, the proposed answer is “R10,500”.","answer":false,"feedback":"R9,000 + R4,500 − R6,000 = R7,500."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the closing bank balance from the stated scenario?”, the proposed answer is “R33,820”.","answer":false,"feedback":"R35,000 + R10,000 − R6,000 − R5,000 − R180 + R7,000 = R40,820."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should the misclassified supplier bill not be captured again?”, the proposed answer is “Equipment cannot be used in accounting software”.","answer":false,"feedback":"The original bill already created the payable, so the correction should fix classification without duplicating the obligation."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Chart of accounts","right":"The structured list of accounts used to classify transactions."},{"left":"Bank feed","right":"Imported bank data presented for matching or controlled transaction creation."},{"left":"Audit trail","right":"Traceable evidence of transactions, changes, approvals and postings."},{"left":"Reconciliation","right":"A comparison of related records followed by investigation of differences."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 1, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"What is the current standard South African VAT rate used in this module?","options":["10%","15%","12%","16%"],"feedback":"The standard VAT rate remains 15% in 2026.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “From 1 April 2026, when does the general compulsory VAT-registration threshold apply?”, the proposed answer is “When accounting profit exceeds R2.3 million”.","answer":false,"feedback":"The general compulsory threshold is based on taxable supplies, not profit, assets or total bank deposits."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “In VAT fundamentals, which statement correctly distinguishes a zero-rated supply from an exempt supply?”, the proposed answer is “A zero-rated supply is taxable at 0%, while an exempt supply is not treated as a taxable supply in the same way”.","answer":true,"feedback":"Zero-rating and exemption have different legal consequences."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why is VAT shown on a supplier invoice not automatically deductible input tax?”, the proposed answer is “Because supplier invoices never support VAT”.","answer":false,"feedback":"A visible VAT amount is only one part of the deduction requirements."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"VAT","right":"Value-Added Tax charged on taxable supplies under South African VAT rules."},{"left":"Vendor","right":"Person registered or required to register for VAT."},{"left":"Output tax","right":"VAT charged on taxable supplies made by the vendor."},{"left":"Input tax","right":"VAT incurred that may be deductible when the legal requirements are met."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 2, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"A standard-rated taxable supply has consideration of R5,500. Which invoice format is required under the ordinary value rule?","options":["No tax invoice is required","A full tax invoice","An abridged tax invoice only","A bank statement is sufficient"],"feedback":"An amount clearly above R5,000 requires the full tax-invoice information. The exact R5,000 boundary is not used as a one-best-answer test because current SARS publications are not fully aligned at that precise value.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the general tax-invoice issue timeframe for a taxable supply above the R50 low-value rule?”, the proposed answer is “21 days”.","answer":true,"feedback":"SARS states that the tax invoice must generally be issued within 21 days of the supply."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Which supply requires a full tax invoice even when consideration is below R5,000?”, the proposed answer is “Every exempt supply”.","answer":false,"feedback":"The abridged-invoice rule does not apply to zero-rated supplies; a full tax invoice is required."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should a bookkeeper do when a supplier tax invoice is missing prescribed information?”, the proposed answer is “Ignore the defect if the VAT amount looks reasonable”.","answer":false,"feedback":"Third-party tax evidence should not be manufactured or altered by the bookkeeper."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Tax invoice","right":"Document meeting prescribed VAT requirements for a taxable supply."},{"left":"Consideration","right":"Amount payable for the supply, including VAT where applicable."},{"left":"Full tax invoice","right":"Tax invoice containing the fuller set of prescribed details."},{"left":"Abridged tax invoice","right":"Simplified tax invoice permitted for lower-value supplies under the applicable rule."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 3, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"How much VAT is included in a standard-rated R11,500 inclusive sale at 15%?","options":["R1,150","R1,500","R10,000","R1,725"],"feedback":"R11,500 × 15/115 = R1,500 VAT.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What should an output-tax schedule primarily reconcile to?”, the proposed answer is “Sales activity and the related VAT ledger postings”.","answer":true,"feedback":"Output tax should trace back to taxable sales and the VAT control records."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the safest treatment of purchase VAT whose deductibility is uncertain?”, the proposed answer is “Keep it as an exception until eligibility is confirmed”.","answer":true,"feedback":"Uncertain input-tax treatment should remain visible and be reviewed before deduction."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why can a correct expense account still produce an incorrect VAT return?”, the proposed answer is “The tax code can be wrong even when the accounting account is right”.","answer":true,"feedback":"Accounting classification and VAT treatment are related but separate checks."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Output VAT","right":"VAT arising on taxable supplies made by a vendor."},{"left":"Input VAT","right":"VAT incurred that may be deductible if applicable requirements are met."},{"left":"VAT control account","right":"Ledger account accumulating VAT amounts for reconciliation and return preparation."},{"left":"VAT payable","right":"Net VAT liability after the applicable calculation for the tax period."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 4, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"What is the VAT on a confirmed standard-rated R8,000 exclusive amount at 15%?","options":["R9,200","R1,200","R1,380","R1,043.48"],"feedback":"R8,000 × 15% = R1,200.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Which formula extracts VAT from a VAT-inclusive amount at a 15% rate?”, the proposed answer is “Inclusive × 15/115”.","answer":true,"feedback":"The 15/115 fraction extracts VAT already contained in the inclusive total."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “How much VAT is included in R23,000 at a 15% inclusive rate?”, the proposed answer is “R20,000”.","answer":false,"feedback":"R23,000 × 15/115 = R3,000."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen when a small rounding difference appears?”, the proposed answer is “Change cents until the batch balances”.","answer":false,"feedback":"Rounding should follow the configured method; differences should not be forced without understanding them."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"VAT-exclusive amount","right":"Price before VAT is added."},{"left":"VAT-inclusive amount","right":"Total price including VAT."},{"left":"VAT fraction","right":"Fraction used to extract VAT from an inclusive amount."},{"left":"Rounding","right":"Applying consistent rules to fractional cents."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 5, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Why should a VAT201 not be prepared from a closing VAT ledger balance alone?”, the proposed answer is “Because the balance may contain opening items, payments, adjustments or unsupported entries that must be analysed”.","answer":true,"feedback":"The return must be supported by reconciled transaction detail and explained ledger movements."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the purpose of an input reconciliation?”, the proposed answer is “To prove every purchase VAT amount is deductible”.","answer":false,"feedback":"Input reconciliation connects potential deductions to purchase records and control balances."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “For eFiling, what is the general VAT201 submission/payment deadline stated by current SARS guidance?”, the proposed answer is “The last business day of the following month”.","answer":true,"feedback":"Current SARS guidance generally allows eFiling submission and payment by the last business day of the following month."},{"id":"q4","answer":2,"prompt":"How long must relevant tax records generally be retained after submission of a return?","options":["Exactly ten years in every case","Three years","Five years","One year"],"feedback":"The ordinary retention period is generally five years, with extensions in certain circumstances.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"VAT201","right":"VAT declaration submitted for a tax period."},{"left":"Tax period","right":"Reporting period assigned to the VAT vendor."},{"left":"VAT reconciliation","right":"Comparison of VAT ledger/control balances to supporting transaction data."},{"left":"Working paper","right":"Schedule showing calculations, sources, adjustments and review evidence."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 6, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"Can the accounting account be correct while the VAT code is wrong?","options":["Yes","Only after year-end","No","Only on bank charges"],"feedback":"Accounting classification and VAT treatment require separate validation.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the VAT effect of duplicating a R23,000 inclusive standard-rated invoice at 15%?”, the proposed answer is “Potential duplicate VAT of R3,000”.","answer":true,"feedback":"R23,000 × 15/115 = R3,000, so the duplicate can repeat that VAT amount."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why do manual VAT journals require additional review?”, the proposed answer is “They automatically create refunds”.","answer":false,"feedback":"Direct VAT journals can materially change the return-support balances outside normal invoice workflows."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen when an error relates to a VAT period already submitted?”, the proposed answer is “Move it silently to the current period”.","answer":false,"feedback":"Prior-period issues require a controlled correction path linked to the original period."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"VAT exception","right":"Transaction or balance requiring clarification, correction or approval before final treatment."},{"left":"Tax-code error","right":"Incorrect VAT category applied in the accounting system."},{"left":"Duplicate claim","right":"VAT amount included more than once because a transaction was duplicated."},{"left":"Cut-off error","right":"Transaction included in the wrong reporting period."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Is accounting profit automatically equal to taxable income?”, the proposed answer is “No; tax law can require adjustments to accounting results”.","answer":true,"feedback":"Accounting profit is an important starting point, but taxable income is determined under tax law."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “A business makes advance income-tax payments based on estimates before its final annual liability is assessed. Which mechanism is this?”, the proposed answer is “A separate tax on turnover”.","answer":false,"feedback":"Provisional tax spreads income-tax payments across the year; it is not a separate tax."},{"id":"q3","answer":2,"prompt":"Which SARS return is used for provisional tax?","options":["IT3(a)","EMP201","IRP6","VAT201"],"feedback":"IRP6 is the provisional-tax return.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “How many compulsory provisional payment periods does SARS generally require?”, the proposed answer is “Three compulsory periods”.","answer":false,"feedback":"SARS describes two compulsory provisional periods and an optional third/top-up payment."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Income tax","right":"Tax determined under the applicable income-tax rules on taxable income."},{"left":"Provisional tax","right":"Advance payment system for income tax based on estimated taxable income."},{"left":"IRP6","right":"SARS provisional-tax return."},{"left":"Taxable income","right":"Amount determined under tax law after applicable inclusions, deductions and adjustments."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(8, 8, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should happen before an authorised eFiling submission?”, the proposed answer is “Log in first and work out the figures later”.","answer":false,"feedback":"eFiling should be the controlled submission step after the figures have been prepared and reviewed."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why must the tax type and period be verified?”, the proposed answer is “Because accurate figures submitted for the wrong tax period are still incorrect”.","answer":true,"feedback":"Entity, tax type and period are core submission controls."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What should be retained after submission?”, the proposed answer is “Nothing if payment was made”.","answer":false,"feedback":"A complete evidence trail supports later review, audit and reconciliation."},{"id":"q4","answer":0,"prompt":"Should the ledger be changed automatically when a SARS statement differs from the books?","options":["No; investigate the reason for the difference first","Only if the business is VAT registered","Yes","Only if the difference is round"],"feedback":"The difference may arise from payment allocation, assessments, timing or prior periods and must be understood first.","type":"mcq"},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"SARS eFiling","right":"SARS electronic platform used for tax returns, declarations, payments and related services."},{"left":"Submission evidence","right":"Proof that a return or declaration was successfully submitted."},{"left":"Statement of account","right":"SARS record showing assessed/declared amounts, payments and balances for the relevant tax type."},{"left":"Compliance correspondence","right":"SARS notice, request or communication requiring review/action."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 1, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Which item is most clearly permanent payroll master data rather than a once-off period input?”, the proposed answer is “Overtime hours for this month”.","answer":false,"feedback":"Banking information belongs to the employee master, while the other items relate to specific pay periods."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the safest response when an employee tax reference is missing?”, the proposed answer is “Record the exception and resolve it through the authorised process”.","answer":true,"feedback":"Missing statutory information should be resolved from authorised records, not fabricated."},{"id":"q3","answer":0,"prompt":"Why are employee bank-detail changes high risk?","options":["They can redirect salary payments","They change gross pay automatically","They remove PAYE","They close the employee record"],"feedback":"Incorrect or fraudulent bank changes can redirect real payroll cash.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should year-to-date payroll openings reconcile to after a system migration?”, the proposed answer is “Approved prior payroll and statutory records”.","answer":true,"feedback":"Opening payroll values should tie to reliable prior payroll and statutory totals."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Employee master record","right":"Core payroll record containing approved employee details used in payroll processing."},{"left":"Remuneration","right":"Amounts paid or payable to an employee, subject to definitions used for payroll and statutory purposes."},{"left":"Payroll period","right":"Weekly, fortnightly, monthly or other approved pay cycle."},{"left":"Pay rate","right":"Approved wage/salary basis used in calculations."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 2, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should hourly ordinary earnings be based on?”, the proposed answer is “The employee''s prior net pay”.","answer":false,"feedback":"Hourly earnings should come from authorised hours and pay rates."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “For employees covered by the relevant BCEA working-time rules, which statement is generally correct about overtime?”, the proposed answer is “It is generally by agreement and subject to working-time limits”.","answer":true,"feedback":"The BCEA generally requires overtime by agreement and sets working-time limits, subject to coverage and lawful variations."},{"id":"q3","answer":1,"prompt":"What is the gross pay from R7,200 basic pay, R405 overtime and a R500 allowance?","options":["R7,605","R8,105","R7,700","R8,500"],"feedback":"R7,200 + R405 + R500 = R8,105.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why can a recurring allowance be duplicated accidentally?”, the proposed answer is “It may already be in the master and also be imported as a period input”.","answer":true,"feedback":"Recurring master values must not be re-entered as separate period earnings without a valid reason."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Basic pay","right":"Employee''s agreed ordinary salary or wage before additions and deductions."},{"left":"Gross pay","right":"Total payroll earnings before deductions for the period."},{"left":"Ordinary hours","right":"Approved normal working hours for payroll purposes."},{"left":"Overtime","right":"Approved work beyond ordinary hours subject to applicable employment terms and law."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 3, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"What is the basic net-pay control formula?","options":["Gross earnings plus employee deductions","Gross earnings minus employee deductions","Employer contributions minus gross earnings","Net pay minus gross earnings"],"feedback":"Net pay is the amount remaining after applicable employee deductions are taken from gross earnings.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Which statement about payroll deductions is safest?”, the proposed answer is “Employer SDL is always deducted from the employee”.","answer":false,"feedback":"Payroll deductions must be supported by an appropriate legal or authorised basis."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Do employer contributions automatically reduce employee net pay?”, the proposed answer is “No; employer costs and employee deductions must be distinguished”.","answer":true,"feedback":"Employer contributions are not simply withheld from employee net pay unless the applicable rules create an employee deduction."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen when a payroll deduction control does not agree to the payroll register?”, the proposed answer is “Investigate the underlying posting or reconciliation difference”.","answer":true,"feedback":"Differences should be traced and explained rather than forced."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Deduction","right":"Amount withheld from gross remuneration according to law, agreement or authorised payroll instruction."},{"left":"Net pay","right":"Amount payable to the employee after applicable deductions."},{"left":"Statutory deduction","right":"Deduction required under applicable law, such as Employees'' Tax or employee UIF where applicable."},{"left":"Voluntary deduction","right":"Authorised deduction such as certain benefits or contributions under workplace arrangements."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 4, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Which statement about PAYE is correct?”, the proposed answer is “PAYE is one flat percentage for all employees”.","answer":false,"feedback":"Employees'' Tax depends on current SARS rules, pay period and employee circumstances rather than one flat rate."},{"id":"q2","answer":2,"prompt":"What are the ordinary UIF contribution percentages under the current rule?","options":["5% employer only","2% employee and 0% employer","1% employee and 1% employer","1% employee only"],"feedback":"UIF is generally 1% from the employee and 1% from the employer, subject to the applicable rules.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the current monthly UIF remuneration ceiling used in this lesson?”, the proposed answer is “R21,254.40”.","answer":false,"feedback":"The current SARS-published monthly UIF ceiling remains R17,712."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Which statement about SDL is correct?”, the proposed answer is “It is normally deducted from employee net pay”.","answer":false,"feedback":"SDL is generally an employer levy at 1% of leviable remuneration for liable employers."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"PAYE / Employees'' Tax","right":"Income tax withheld by employers from remuneration under the applicable deduction rules."},{"left":"UIF","right":"Unemployment Insurance Fund contribution system."},{"left":"SDL","right":"Skills Development Levy paid by liable employers."},{"left":"EMP201","right":"Monthly Employer Declaration used to declare applicable PAYE, SDL, UIF and related amounts."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 5, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the main difference between a payroll register and a payslip?”, the proposed answer is “The payroll register is an internal detailed payroll report; the payslip is employee-facing period information”.","answer":true,"feedback":"The register supports internal payroll review while the payslip communicates the individual employee''s pay result."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Does a payslip by itself prove that an overtime input was authorised?”, the proposed answer is “Only if net pay is positive”.","answer":false,"feedback":"Payslips are outputs and do not replace source-input approval."},{"id":"q3","answer":0,"prompt":"What is the safest treatment of a valid payroll input received after cut-off?","options":["Use the authorised late-input or correction process","Change the prior payslip manually","Delete it","Insert it secretly into the approved run"],"feedback":"Late inputs should be handled through a controlled process that preserves approval and recalculation evidence.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “How long must BCEA time-worked and remuneration records generally be retained?”, the proposed answer is “Exactly ten years”.","answer":false,"feedback":"The BCEA generally requires these records for three years from the date of the last entry."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Payroll source document","right":"Evidence supporting a payroll input or change."},{"left":"Payslip","right":"Employee-facing record summarising earnings, deductions and net pay for a payroll period."},{"left":"Payroll register","right":"Detailed payroll report listing calculations and totals for employees."},{"left":"Change form","right":"Authorised document supporting a master-data or pay change."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 6, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What should the salary payment file total agree to before release?”, the proposed answer is “The approved net-pay control total from payroll”.","answer":true,"feedback":"The salary payment file should match the approved employee net-pay total."},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why is an employee-count reconciliation useful?”, the proposed answer is “It can detect missing, duplicate or terminated employees”.","answer":true,"feedback":"Comparing the payroll population to authorised employee records can identify population errors before payment."},{"id":"q3","answer":2,"prompt":"What should happen if a bank-detail change occurred shortly before payroll release?","options":["Pay to both bank accounts","Delete the employee","Review the approved verification before release","Ignore it because payroll totals balance"],"feedback":"Bank changes are high-risk and should be verified before the payment file is released.","type":"mcq"},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the purpose of segregating payroll preparation from final payment release?”, the proposed answer is “To avoid reconciliations”.","answer":false,"feedback":"Segregation adds independent review between calculation and cash release."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Payroll reconciliation","right":"Comparison of payroll calculations to supporting records, ledger accounts and payment schedules."},{"left":"Net-pay schedule","right":"List of employee net amounts approved for salary payment."},{"left":"Payroll liability","right":"Amount owed to employees, SARS or another payroll-related party."},{"left":"Payment release","right":"Authorised final action causing salary or statutory payment to leave the bank."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 7, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the safest first action when a payroll report is sent to an unauthorised recipient?”, the proposed answer is “Change all employee salaries”.","answer":false,"feedback":"Payroll confidentiality incidents should be escalated promptly through the organisation''s authorised process."},{"id":"q2","answer":2,"prompt":"How should an omitted current-period earning normally be corrected before finalisation?","options":["By editing the payslip PDF","By changing PAYE only","By fixing the authorised source input and rerunning the payroll review","By increasing only the bank-payment file so the employee receives the money without changing the authorised payroll source records"],"feedback":"Correcting the source input keeps earnings, deductions, ledger and payment calculations aligned.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why is a prior-period payroll error more complex?”, the proposed answer is “It automatically disappears at year-end”.","answer":false,"feedback":"Prior-period corrections may affect multiple accounting and statutory records."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should payroll audit history preserve?”, the proposed answer is “The original issue, authority, correction and resulting records”.","answer":true,"feedback":"A complete correction trail shows what was wrong, how it was authorised and how it was resolved."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Payroll confidentiality","right":"Restricting payroll information to authorised people and legitimate purposes."},{"left":"Payroll correction","right":"Authorised change fixing an incorrect payroll input or result."},{"left":"Audit trail","right":"Traceable history of payroll transactions, changes, approvals and users."},{"left":"Prior-period correction","right":"Correction affecting a payroll period already finalised or reported."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(9, 8, '{"version":2,"questions":[{"id":"q1","answer":0,"prompt":"What is the total gross earnings in the three-employee practical?","options":["R45,250","R50,250","R40,170.38","R46,132.12"],"feedback":"R20,000 + R14,500 + R10,750 = R45,250.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the total approved net pay in the practical?”, the proposed answer is “R39,740.76”.","answer":false,"feedback":"The three employee net amounts total R40,170.38."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the simplified EMP201 support total before ETI or other adjustments?”, the proposed answer is “R5,311.74”.","answer":true,"feedback":"PAYE R4,000 + employee UIF R429.62 + employer UIF R429.62 + SDL R452.50 = R5,311.74."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why does the payroll journal credit UIF Payable with R859.24 in this exercise?”, the proposed answer is “It combines the employee and employer UIF portions”.","answer":true,"feedback":"R429.62 employee UIF plus R429.62 employer UIF creates the total UIF liability of R859.24."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Gross pay","right":"Earnings before authorised deductions are subtracted."},{"left":"Deduction","right":"An authorised amount subtracted from an employee’s gross pay."},{"left":"Net pay","right":"The amount payable after authorised deductions."},{"left":"Payroll reconciliation","right":"A comparison of payroll inputs, outputs, payments and control totals."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 1, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “Why must the opening subsidiary debtor list agree to Debtors Control before current transactions are processed?”, the proposed answer is “To avoid using a chart of accounts”.","answer":false,"feedback":"Opening customer detail and the control account should describe the same receivable position before the capstone continues."},{"id":"q2","answer":1,"prompt":"Which action is outside the learner''s routine authority in this simulation?","options":["Updating the evidence register","Approving an unusual manual journal without review","Capturing a supported routine customer receipt","Preparing a bank reconciliation"],"feedback":"Unusual manual journals require the fictional manager or reviewer approval defined by the authority matrix.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the purpose of the evidence register?”, the proposed answer is “To link project records and outputs to their supporting evidence and status”.","answer":true,"feedback":"The evidence register makes the project traceable and shows whether supporting records are complete, checked or still exceptions."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What should happen when an opening balance difference cannot yet be explained?”, the proposed answer is “Post it to miscellaneous expense”.","answer":false,"feedback":"Opening differences must remain visible and be resolved rather than forced into a balancing entry."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Capstone","right":"Integrated final practical project demonstrating multiple course skills."},{"left":"Opening balance","right":"Balance carried into the start of an accounting period."},{"left":"Control point","right":"Required check or approval in a workflow."},{"left":"Evidence index","right":"Register linking each project output to its supporting evidence."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 2, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the main purpose of an account-use rule in the capstone chart?”, the proposed answer is “To define which transactions belong in an account and reduce inconsistent coding”.","answer":true,"feedback":"Account-use rules make classifications consistent and reduce duplicate or ambiguous coding."},{"id":"q2","answer":1,"prompt":"What is the correct opening Debtors Control balance for the project?","options":["R10,000 credit","R5,000 debit","R45,000 credit","R4,250 debit"],"feedback":"The customer opening list totals R5,000 debit and must agree to Debtors Control.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What should happen if the supplier opening list totals R9,500 but Creditors Control is R10,000?”, the proposed answer is “Ignore it because the trial balance balances”.","answer":false,"feedback":"A subsidiary-control mismatch is an unresolved opening issue and must be investigated from evidence."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should opening balances not be treated as current-month income or expense?”, the proposed answer is “They never appear in financial reports”.","answer":false,"feedback":"Opening balances carry forward the prior position and should not be re-created as current-period performance."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Chart of accounts","right":"Structured list of ledger accounts used by the business."},{"left":"Account code","right":"Identifier assigned to a ledger account."},{"left":"Opening balance","right":"Balance brought forward into the current period."},{"left":"Control account","right":"General-ledger account summarising related subsidiary records."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 3, '{"version":2,"questions":[{"id":"q1","answer":2,"prompt":"How should the R5,000 owner contribution be classified in the capstone?","options":["Service revenue","Accounts payable","Equity funding","Cleaning expense"],"feedback":"For this capstone, the supplied evidence identifies the R5,000 as an equity contribution, so it increases Bank and Equity rather than operating revenue. Live shareholder funding must be classified from its supporting evidence.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “Why does Customer A''s R10,000 receipt not create another R10,000 of revenue?”, the proposed answer is “Because customer receipts are always expenses”.","answer":false,"feedback":"The receipt settles a receivable created by the earlier sale and should not duplicate revenue."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What remains in Supplier X''s account after opening R6,000 credit, a R3,000 invoice and a R7,000 payment?”, the proposed answer is “R16,000 credit”.","answer":false,"feedback":"R6,000 + R3,000 − R7,000 = R2,000 payable."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is the correct treatment of the R1,000 transfer from Bank to Petty Cash?”, the proposed answer is “Transfer between asset accounts”.","answer":true,"feedback":"The transfer moves cash from Bank to Petty Cash; it does not create income or expense."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Batch","right":"Group of transactions processed together."},{"left":"Transaction analysis","right":"Determining what happened economically and which accounts are affected."},{"left":"Duplicate check","right":"Review to prevent the same transaction being captured more than once."},{"left":"Allocation","right":"Linking a transaction to the correct customer, supplier, account or reference."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 4, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"What is Customer B''s closing balance before period-end adjustments?","options":["R1,250 debit","R3,250 debit","R4,250 debit","R5,750 debit"],"feedback":"R1,750 opening + R4,000 sale − R2,000 receipt − R500 credit note = R3,250 debit.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the closing Creditors Control balance after the listed supplier transactions?”, the proposed answer is “R5,400 credit”.","answer":true,"feedback":"Supplier X closes at R2,000 and Supplier Y at R3,400, giving R5,400 total creditors."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the internal Bank balance before bank reconciliation?”, the proposed answer is “R19,120 debit”.","answer":true,"feedback":"The opening balance plus all recorded receipts less all recorded payments gives R19,120 debit."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why does Payroll Statutory Payable remain at R1,500 after net salaries are paid?”, the proposed answer is “Because the net-pay payment clears only Net Salaries Payable”.","answer":true,"feedback":"The R7,500 salary payment clears the employee net-pay liability; the separate R1,500 statutory liability remains outstanding in the capstone."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Journal","right":"Chronological transaction record used before or during ledger posting."},{"left":"General ledger","right":"Main set of accounts summarising the financial effects of transactions."},{"left":"Subsidiary ledger","right":"Detailed customer, supplier or other supporting records linked to a control account."},{"left":"Cashbook","right":"Record of bank and cash receipts/payments."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 5, '{"version":2,"questions":[{"id":"q1","answer":1,"prompt":"What is the reconciled internal Bank balance for the capstone?","options":["R22,120 debit","R19,120 debit","R20,120 debit","R17,120 debit"],"feedback":"R20,120 statement + R2,000 outstanding deposit − R3,000 unpresented EFT = R19,120 cashbook.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “When is the R3,000 Supplier Y payment a valid unpresented bank item?”, the proposed answer is “When it was recorded and released before cut-off but has not yet cleared the bank”.","answer":true,"feedback":"An unpresented payment must be a genuine recorded and released payment awaiting bank processing, not an unapproved intention."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is the customer schedule total before the period-end write-off?”, the proposed answer is “R15,750 debit”.","answer":false,"feedback":"Customer A R12,500 + B R3,250 + C R750 = R16,500 debit."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why can Debtors Control agree while customer records are still wrong?”, the proposed answer is “A receipt can be allocated to the wrong customer without changing the control total”.","answer":true,"feedback":"Misallocation between customers can preserve the total receivable while making individual balances incorrect."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Bank reconciliation","right":"Comparison of internal bank records to the external bank statement."},{"left":"Reconciling item","right":"Timing or recording difference explaining why two related balances differ."},{"left":"Outstanding deposit","right":"Receipt recorded internally but not yet reflected by the bank."},{"left":"Unpresented payment","right":"Payment recorded internally but not yet reflected by the bank."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 6, '{"version":2,"questions":[{"id":"q1","answer":2,"prompt":"How much of the R6,000 six-month insurance payment remains prepaid after September?","options":["R6,000","R7,000","R5,000","R1,000"],"feedback":"One month is R1,000 expense, leaving five months or R5,000 as a prepayment.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the accounting effect of the R900 approved utilities accrual?”, the proposed answer is “Increase Prepaid Insurance”.","answer":false,"feedback":"The current-period service is recognised as expense with a liability because the invoice has not yet been recorded."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “Why is Customer C''s R750 write-off acceptable in the capstone?”, the proposed answer is “The fictional manager approved a specific write-off based on supplied irrecoverability evidence”.","answer":true,"feedback":"The write-off is based on specific evidence and authority, not age alone."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “What is Debtors Control after the approved Customer C write-off?”, the proposed answer is “R15,750 debit”.","answer":true,"feedback":"R16,500 pre-adjustment debtors less R750 written off = R15,750."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Period-end adjustment","right":"Entry made to update accounts before final reporting."},{"left":"Accrual","right":"Expense or income recognised before cash settlement where applicable."},{"left":"Prepayment","right":"Payment relating partly or wholly to a future period."},{"left":"Depreciation","right":"Allocation of the depreciable amount of an asset over its useful life under the chosen accounting policy."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 7, '{"version":2,"questions":[{"id":"q1","answer":3,"prompt":"What is total capstone revenue after the Customer B credit note?","options":["R27,430","R30,000","R26,000","R29,500"],"feedback":"Service Revenue R26,000 + Office Support Revenue R3,500 = R29,500.","type":"mcq"},{"id":"q2","type":"true_false","prompt":"True or false — for the question “What is the current-period profit after all approved adjustments?”, the proposed answer is “R2,070”.","answer":true,"feedback":"R29,500 revenue − R27,430 expenses = R2,070 profit."},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What is total assets on the final statement of financial position?”, the proposed answer is “R52,070”.","answer":false,"feedback":"Bank, petty cash, debtors, prepayment and net equipment total R59,870."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why is presented equity R52,070 when the trial-balance Equity account is R50,000?”, the proposed answer is “Because Creditors are added to Equity”.","answer":false,"feedback":"The current-period result remains in open income and expense accounts but is included in total equity for financial-position presentation."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Statement of Profit or Loss","right":"Report summarising income and expenses for a period."},{"left":"Statement of Financial Position","right":"Report showing assets, liabilities and equity at a point in time."},{"left":"Control schedule","right":"Supporting schedule explaining a ledger balance."},{"left":"Cross-check","right":"Comparison between related reports or records."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}'),
(10, 8, '{"version":2,"questions":[{"id":"q1","type":"true_false","prompt":"True or false — for the question “What is the strongest evidence that the capstone portfolio is traceable?”, the proposed answer is “The reports use large headings”.","answer":false,"feedback":"Traceability means another person can reproduce the accounting path from evidence to report."},{"id":"q2","answer":1,"prompt":"Which open item belongs in the final handover?","options":["No timing items because the bank already reconciled","The R1,500 payroll statutory liability awaiting settlement","Only items that change revenue","Passwords for the bank account"],"feedback":"Outstanding liabilities and timing items still require ownership and later evidence even when the current period is reconciled.","type":"mcq"},{"id":"q3","type":"true_false","prompt":"True or false — for the question “What should an improvement plan include?”, the proposed answer is “Problem, likely root cause, control, owner, target date and success measure”.","answer":true,"feedback":"A useful improvement plan assigns a practical control and a way to evaluate whether it worked."},{"id":"q4","type":"true_false","prompt":"True or false — for the question “Why should the R3,000 unpresented EFT be followed in the next period?”, the proposed answer is “To confirm it eventually cleared or identify a failed/incorrect payment”.","answer":true,"feedback":"Timing items need later clearing evidence; otherwise they may hide failed or incorrectly recorded transactions."},{"id":"q5","type":"matching","prompt":"Match each bookkeeping term to its correct description.","pairs":[{"left":"Portfolio","right":"Organised collection of evidence demonstrating completed bookkeeping work."},{"left":"Handover","right":"Structured transfer of records, status, responsibilities and outstanding actions."},{"left":"Outstanding item","right":"Task, difference or document that remains unresolved."},{"left":"Continuous improvement","right":"Systematic effort to improve processes based on evidence and recurring issues."}],"feedback":"Review the lesson’s Key Terms & Concepts and the way each term is applied in the lesson."}]}');
