-- Bookkeeping lesson knowledge-check correction
-- Preserves lesson IDs, lesson completion history, progression, and the five-check lesson standard.

begin;

create temporary table _bookkeeping_knowledge_fix (
  module_number integer not null,
  lesson_number integer not null,
  knowledge_check text not null,
  primary key (module_number, lesson_number)
) on commit drop;


do $$
declare
  matched_count integer;
begin
  select count(*) into matched_count
  from _bookkeeping_knowledge_fix f
  join public.course_modules m
    on m.course_id = 'fcbe0c39-c31f-4a39-833f-7b89d553bef2'::uuid
   and m.module_number = f.module_number
  join public.lessons l
    on l.module_id = m.id
   and l.lesson_number = f.lesson_number;

  if matched_count <> 80 then
    raise exception 'Bookkeeping knowledge-check guard failed: matched %, expected 80', matched_count;
  end if;
end $$;

update public.lessons l
set knowledge_check = f.knowledge_check,
    updated_at = now()
from _bookkeeping_knowledge_fix f
join public.course_modules m
  on m.course_id = 'fcbe0c39-c31f-4a39-833f-7b89d553bef2'::uuid
 and m.module_number = f.module_number
where l.module_id = m.id
  and l.lesson_number = f.lesson_number;

commit;
